-- Option type: Some(value) or None
type Option[a] = Some(a) | None

-- Safe square root: Some(sqrt(n)) if n >= 0, None if n < 0
pure func safeSqrt(n: float) -> Option[float] =
  if n >= 0.0 then Some(sqrt(n)) else None

func printResult(r: Option[float]) -> () ! {IO} =
