import std/io (println)

-- Compute F(n): tail-recursive Fibonacci where F(1)=1, F(2)=1
pure func fibN(n: int) -> int ! {} {
  letrec go = \i. \a. \b. if i > n then a else go(i + 1)(b)(a + b);
  if n <= 0 then 0
  else if n == 1 then 1
  else go(2)(1)(1)
}

-- Sum of first n Fibonacci numbers = F(n+2) - 1
pure func fibSum(n: int) -> int ! {} {
  fibN(n + 2) - 1
}

export func main() -> () ! {IO} {
  let result = fibSum(20);
  println(show(result));
  println(show(result))
}

