module benchmark/solution

let MOD: int = 1000000007

pure func matMul(a: [int], b: [int]) -> [int] ! {} {
  match (a, b) {
    (
      [a00, a01, a02, a10, a11, a12, a20, a21, a22],
      [b00, b01, b02, b10, b11, b12, b20, b21, b22]
    ) => [
      (a00 * b00 + a01 * b10 + a02 * b20) % MOD,
      (a00 * b01 + a01 * b11 + a02 * b21) % MOD,
      (a00 * b02 + a01 * b12 + a02 * b22) % MOD,
      (a10 * b00 + a11 * b10 + a12 * b20) % MOD,
      (a10 * b01 + a11 * b11 + a12 * b21) % MOD,
      (a10 * b02 + a11 * b12 + a12 * b22) % MOD,
      (a20 * b00 + a21 * b10 + a22 * b20) % MOD,
      (a20 * b01 + a21 * b11 + a22 * b21) % MOD,
      (a20 * b02 + a21 * b12 + a22 * b22) % MOD
    ]
  }
}

pure func matPow(matrix: [int], exp: int) -> [int] ! {} {
  if exp == 0 then
    [1, 0, 0, 0, 1, 0, 0, 0, 1]
  else if exp % 2 == 0 then
    matPow(matMul(matrix, matrix), exp / 2)
  else
    matMul(matrix, matPow(matMul(matrix, matrix), (exp - 1) / 2))
}

pure func countNo101(n: int) -> int ! {} {
  let M = [1, 0, 1, 1, 1, 0, 0, 1, 0];
  match matPow(M, n) {
    [v0, _, _, v1, _, _, v2, _, _] => (v0 + v1 + v2) % MOD
  }
}

export func main() -> () ! {IO} {
  println(show(countNo101(1000000000000000000)));
  println(show(countNo101(987654321987654321)))
}

