class Leaf {
  constructor(value) {
    this.type = 'leaf';
    this.value = value;
   }
}

class Branch {
  constructor(left, value, right) {
    this.type = 'branch';
    this.left = left;
    this.value = value;
    this.right = right;
   }
}

function treeSum(node) {
  if (node.type === 'leaf') {
    return node.value;
   }
  return treeSum(node.left) + node.value + treeSum(node.right);
}

function main() {
  const tree = new Branch(
    new Branch(new Leaf(1), 3, new Leaf(4)),
    5,
    new Branch(new Leaf(null), 8, new Leaf(10))
   );

  const sum = treeSum(tree);
  console.log(sum);
}

main();

