from dataclasses import dataclass
from typing import Optional, Union


@dataclass
class Leaf:
    value: int


@dataclass
class Branch:
    left: "Node"
    value: int
    right: "Node"


Node = Union[Leaf, Branch]


def treeSum(node: Node) -> int:
    if isinstance(node, Leaf):
        return node.value
    elif isinstance(node, Branch):
        return treeSum(node.left) + node.value + treeSum(node.right)
    raise TypeError(f"Unknown node type: {type(node)}")


def main() -> None:
    #          5
    #         / \
    #        3    8
    #       / \    \
    #      1    4   10
    #
    # In the Leaf/Branch ADT, an "empty" leaf is represented by Leaf(0).
    # 8 has only a right child (10), so its left side is Leaf(0).
    tree: Node = Branch(
        left=Branch(
            left=Leaf(1),
            value=3,
            right=Leaf(4),
        ),
        value=5,
        right=Branch(
            left=Leaf(0),
            value=8,
            right=Leaf(10),
        ),
    )
    print(treeSum(tree))


if __name__ == "__main__":
    main()

