module benchmark/solution

import std/io (println)
import std/list (nth, map)

type Instr = PUSH(int) | ADD | SUB | MUL | DUP | OVER | SWAP | POP | JMP(int) | JMPZ(int) | JMPGT(int) | HALT

let program: [Instr] = [
  PUSH(252),
  PUSH(105),
  OVER,
  OVER,
  SUB,
  JMPZ(12),
  OVER,
  OVER,
  JMPGT(4),
  OVER,
  SUB,
  JMP(-9),
  SWAP,
  OVER,
  SUB,
  SWAP,
  JMP(-14),
  POP,
  HALT
]

type VMResult = { stack: [int], steps: int }

pure func instrName(i: Instr) -> string {
  match i {
    PUSH(k) => "PUSH(${show(k)})",
    ADD      => "ADD",
    SUB      => "SUB",
    MUL      => "MUL",
    DUP      => "DUP",
    OVER     => "OVER",
    SWAP     => "SWAP",
    POP      => "POP",
    JMP(d)   => "JMP(${show(d)})",
    JMPZ(d)  => "JMPZ(${show(d)})",
    JMPGT(d) => "JMPGT(${show(d)})",
    HALT     => "HALT"
   }
}

func exec(pc: int, stack: [int], steps: int) -> VMResult ! {} {
  let instr = nth(program, pc);
  match instr {
    None => { stack: stack, steps: steps },
    Some(i) => match i {
      HALT            => { stack: stack, steps: steps + 1 },
      PUSH(k)         => exec(pc + 1, k :: stack, steps + 1),
      ADD             => match stack {
           b :: a :: rest => exec(pc + 1, (a + b) :: rest, steps + 1),
          _               => exec(pc + 1, stack, steps + 1)
        },
      SUB             => match stack {
           b :: a :: rest => exec(pc + 1, (a - b) :: rest, steps + 1),
          _               => exec(pc + 1, stack, steps + 1)
        },
      MUL             => match stack {
           b :: a :: rest => exec(pc + 1, (a * b) :: rest, steps + 1),
          _               => exec(pc + 1, stack, steps + 1)
        },
      DUP             => match stack {
           x :: rest      => exec(pc + 1, x :: x :: rest, steps + 1),
          _                => exec(pc + 1, stack, steps + 1)
        },
      OVER            => match stack {
           b :: a :: rest => exec(pc + 1, a :: b :: a :: rest, steps + 1),
          _                => exec(pc + 1, stack, steps + 1)
        },
      SWAP            => match stack {
           b :: a :: rest => exec(pc + 1, a :: b :: rest, steps + 1),
          _                => exec(pc + 1, stack, steps + 1)
        },
      POP             => match stack {
           _ :: rest      => exec(pc + 1, rest, steps + 1),
          _                => exec(pc + 1, stack, steps + 1)
        },
      JMP(d)          => exec(pc + d, stack, steps + 1),
      JMPZ(d)         => match stack {
           v :: rest      => if v == 0 then exec(pc + d, rest, steps + 1) else exec(pc + 1, rest, steps + 1),
          _                => exec(pc + 1, stack, steps + 1)
        },
      JMPGT(d)        => match stack {
           b :: a :: rest => if a > b then exec(pc + d, rest, steps + 1) else exec(pc + 1, rest, steps + 1),
          _                => exec(pc + 1, stack, steps + 1)
        }
     }
   }
}

func printBottomToTop(stack: [int]) -> () ! {IO} =
  match stack {
    []         => (),
    x :: r      => {
      printBottomToTop(r);
      println(show(x))
     }
   }

export func main() -> () ! {IO} {
  let result = exec(0, [], 0);
  printBottomToTop(result.stack);
  println("steps: ${show(result.steps)}")
}

