#!/usr/bin/env python3
"""Read a file from the CLI argument, sum the numbers it contains, and print the result."""

import sys
from pathlib import Path


def main() -> int:
    if len(sys.argv) < 2:
        print("usage: solution.py <file>", file=sys.stderr)
        return 1

    path = Path(sys.argv[1])
    total = 0
    with path.open("r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line:
                total += int(line)
    print(total)
    return 0


if __name__ == "__main__":
    sys.exit(main())

