module benchmark/solution

import std/fs (readFile, writeFile)
import std/json (decode, getString, getNumber, getArray)
import std/string (split)
import std/list (length)
import std/option (Option, Some, None)
import std/math (floatToInt)

-- Validate config from parsed JSON, returns Option of display string
pure func validateConfig(app_name: string, version: string, port: int, features: [Json]) -> Option[string] = {
  let parts = split(version, ".");
  let has_two_dots = length(parts) == 3;
  let valid_port = port >= 1024 && port <= 65535;
  let non_empty_features = length(features) > 0;
  if has_two_dots && valid_port && non_empty_features then
    Some("Loaded ${app_name} v${version} on port ${show(port)} with ${show(length(features))} features")
  else
    None
}

export func main() -> () ! {IO, FS} {
       -- Write the config file
  writeFile("app_config.json", "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}");

       -- Read the config file (returns string directly)
  let content = readFile("app_config.json");

       -- Parse JSON and validate
  match decode(content) {
    Err(msg) => println("Error parsing JSON: ${msg}"),
    Ok(parsed) => {
      let app_name = match getString(parsed, "app_name") {
        Some(s) => s,
        None => ""
           };
      let version = match getString(parsed, "version") {
        Some(s) => s,
        None => ""
           };
      let port = match getNumber(parsed, "port") {
        Some(n) => floatToInt(n),
        None => 0
           };
      let features = match getArray(parsed, "features") {
        Some(arr) => arr,
