	"fmt"
	"os"
	"strings"
)

type Config struct {
	AppName  string   `json:"app_name"`
	Version  string   `json:"version"`
	Port     int      `json:"port"`
	Features []string `json:"features"`
}

func main() {
	// Create the config file
	configJSON := `{
		"app_name": "MyApp",
		"version": "1.0.0",
		"port": 8080,
		"features": ["logging", "auth", "api"]
	}`

	err := os.WriteFile("app_config.json", []byte(configJSON), 0644)
	if err != nil {
		fmt.Println("Error creating config file:", err)
		os.Exit(1)
	}

	// Load and validate the config
	cfg, err := loadAndValidateConfig("app_config.json")
	if err != nil {
		fmt.Println("Error loading config:", err)
		os.Exit(1)
	}

	// Print the result in exact format required
	fmt.Printf("Loaded %s v%s on port %d with %d features\n",
		cfg.AppName, cfg.Version, cfg.Port, len(cfg.Features))
}

func loadAndValidateConfig(filename string) (*Config, error) {
	data, err := os.ReadFile(filename)
	if err != nil {
		return nil, err
	}

	var config Config
	err = json.Unmarshal(data, &config)
	if err != nil {
		return nil, err
	}

	// Validate port is between 1024 and 65535
	if config.Port < 1024 || config.Port > 65535 {
		return nil, fmt.Errorf("port must be between 1024 and 65535")
	}

	// Validate version contains exactly two dots (X.Y.Z format)
	dotCount := strings.Count(config.Version, ".")
	if dotCount != 2 {
		return nil, fmt.Errorf("version must contain exactly two dots (X.Y.Z format)")
	}

	// Validate features list is not empty
	if len(config.Features) == 0 {
		return nil, fmt.Errorf("features list cannot be empty")
	}

	return &config, nil
}

