import { writeFileSync, readFileSync } from 'fs';

const configPath = './app_config.json';

function createConfigFile() {
  const config = {
    app_name: "MyApp",
    version: "1.0.0",
    port: 8080,
    features: ["logging", "auth", "api"]
  };
  writeFileSync(configPath, JSON.stringify(config, null, 2));
}

function validateConfig(config) {
  const errors = [];

  if (config.port < 1024 || config.port > 65535) {
    errors.push('Port must be between 1024 and 65535');
  }

  const dotCount = (config.version.match(/\./g) || []).length;
  if (dotCount !== 2) {
    errors.push('Version must contain exactly two dots (X.Y.Z format)');
  }

  if (!config.features || config.features.length === 0) {
    errors.push('Features list must not be empty');
  }

  return errors;
}

