import std/list (head, length as listLength, tail)
import std/string (chars, intToStr, stringToInt, repeat)
import std/option (Some, None, getOrElse, isSome)

-- Use a local binding to pick the right length for char lists
pure func charListLen(cs: [string]) -> int =
  listLength(cs)

pure func countSame(target: string, cs: [string]) -> int {
  match cs {
    [] => 0,
    c :: rest => if c == target then 1 + countSame(target, rest) else 0
    }
}

pure func skipN(n: int, cs: [string]) -> [string] {
  match n {
     0            => cs,
     _ => match cs {
       []         => [],
       _ :: r      => skipN(n - 1, r)
      }
    }
}

pure func encodeChars(cs: [string]) -> string {
  match cs {
    []         => "",
    c :: rest => {
      let count = 1 + countSame(c, rest);
      let remaining = skipN(count - 1, rest);
       "${intToStr(count)}${c}${encodeChars(remaining)}"
     }
   }
}

export func encode(s: string) -> string =
  encodeChars(chars(s))

pure func parseDigits(cs: [string], acc: int) -> Option[(int, [string])] {
  match cs {
    []         => Some((acc, [])),
    c :: rest => {
      match stringToInt(c) {
        Some(n) => parseDigits(rest, acc * 10 + n),
        None     => Some((acc, cs))
       }
     }
   }
}

pure func nextPair(cs: [string]) -> Option[(int, string, [string])] {
  match parseDigits(cs, 0) {
    Some((num, rest)) => {
      let optC = head(rest);
      if isSome(optC) then
        Some((num, getOrElse(optC, ""), tail(rest)))
      else None
     },
    None => None
   }
}

export func decode(s: string) -> string =
  decodeChars(chars(s))

pure func decodeChars(cs: [string]) -> string {
  match nextPair(cs) {
    None                          => "",
    Some((n, c, rest)) => "${repeat(c, n)}${decodeChars(rest)}"
   }
}

export func roundtrip(s: string) -> bool =
  s == decode(encode(s))

export func singleCharEncode(s: string) -> bool =
  if charListLen(chars(s)) == 1 then
    s == decode(encode(s))
  else false

export func main() -> () ! {IO} {
  println(encode("aaabbc"));
  println(encode("xyz"));
  println(decode("3a2b1c"));
  println(decode("1x1y1z"));
  println(show(roundtrip("hello")));
  println(show(singleCharEncode("q")))
}

