def encode(text: str) -> str:
    if not text:
        return ""

    result = []
    previous = text[0]
    count = 1

    for character in text[1:]:
        if character == previous:
            count += 1
        else:
            result.append(f"{count}{previous}")
            previous = character
            count = 1

    result.append(f"{count}{previous}")
    return "".join(result)


def decode(encoded: str) -> str:
    result = []
    index = 0

    while index < len(encoded):
        start = index
        while index < len(encoded) and "0" <= encoded[index] <= "9":
            index += 1

        if index == start or index == len(encoded):
            raise ValueError("Each run must contain a count followed by a character.")

        count = int(encoded[start:index])
        if count < 1:
            raise ValueError("Run counts must be positive.")

        result.append(encoded[index] * count)
        index += 1

    return "".join(result)


def roundtrip(text: str) -> bool:
    assert decode(encode(text)) == text
    return True


def singleCharEncode(character: str) -> bool:
    if len(character) != 1:
        raise ValueError("Expected exactly one character.")
    assert encode(character) == f"1{character}"
    return True


def main() -> None:
    print(encode("aaabbc"))
    print(encode("xyz"))
    print(decode("3a2b1c"))
    print(decode("1x1y1z"))
    print(roundtrip("hello"))
    print(singleCharEncode("q"))


if __name__ == "__main__":
    main()

