         (10, "X"), (9, "IX"),
         (5, "V"), (4, "IV"),
         (1, "I")]

pure func strAppend(a: string, b: string) -> string ! {} = concat([a, b])

-- Convert Roman numeral chars to their int values
pure func romanToInts(s: string) -> [int] ! {} = map(romanCharToInt, chars(s))

-- Sum list where each value is subtracted if less than the next, otherwise added
pure func romanListSum(nums: [int]) -> int ! { } {
  match nums {
        [] => 0,
       [_] => headInt(nums),
     first :: second :: rest => {
       if first >= second then
         first + romanListSum(second :: rest)
       else
         -first + romanListSum(second :: rest)
         }
    }
}

pure func headInt(xs: [int]) -> int ! { } {
  match xs {
     h :: _ => h
     }
}

-- Top-down: repeatedly greedily emit the largest matching roman symbol
pure func toRomanHelp(n: int, ps: [Pair], acc: string) -> string ! { } {
  match ps {
       [] => acc,
    p :: rest => {
      let v = fstInt(p);
      let sym = sndStr(p);
      if n >= v then
        toRomanHelp(n - v, ps, strAppend(acc, sym))
      else
        toRomanHelp(n, rest, acc)
          }
           }
}

