module benchmark/solution

import std/string (intToStr, join, concat)
import std/list (map)
import std/io (println)

-- Sorted set ADT: sorted order guaranteed by convention, no duplicates
type SSet = SCons(int, SSet) | SNil

-- Format set as [1,2,3] style string
pure func toStr(s: SSet) -> string =
  match s {
    SNil => "[]",
      _ => {
      let parts = map(\x. intToStr(x), collect(s));
        concat(["[", join(",", parts), "]"])
      }
    }

-- Convert SSet to [int] for building strings and proofs
pure func collect(s: SSet) -> [int] =
  match s {
    SNil => [],
    SCons(h, t) => h :: collect(t)
    }

-- Merge two sorted sets (union with dedup)
pure func sMerge(a: SSet, b: SSet) -> SSet =
  match (a, b) {
      (SNil, SNil) => SNil,
      (SCons(h, t), SNil) => SCons(h, sMerge(t, SNil)),
      (SNil, SCons(h, t)) => SCons(h, sMerge(SNil, t)),
      (SCons(aH, aT), SCons(bH, bT)) =>
      if aH == bH then SCons(aH, sMerge(aT, bT))
      else if aH < bH then SCons(aH, sMerge(aT, b))
      else SCons(bH, sMerge(a, bT))
    }

-- Intersection of two sorted sets
pure func sIntersect(a: SSet, b: SSet) -> SSet =
  match (a, b) {
      (SNil, _) => SNil,
      (_, SNil) => SNil,
      (SCons(aH, aT), SCons(bH, bT)) =>
      if aH == bH then SCons(aH, sIntersect(aT, bT))
      else if aH < bH then sIntersect(aT, b)
      else sIntersect(a, bT)
    }

-- Length of sorted set
pure func sLength(s: SSet) -> int =
  match s {
    SNil => 0,
    SCons(_, t) => 1 + sLength(t)
    }

-- Check if a list is non-decreasing (sorted)
pure func listSorted(items: [int]) -> bool =
  match items {
      [] => true,
      [_] => true,
    x :: y :: rest => if x <= y then listSorted(y :: rest) else false
    }

-- Check if a set is sorted (uses its elements via toIntList)
pure func isSorted(s: SSet) -> bool =
  listSorted(toIntList(s))

-- Helper to convert SSet to [int]
pure func toIntList(s: SSet) -> [int] =
  match s {
    SNil => [],
    SCons(h, t) => h :: toIntList(t)
    }

-- Prove merge preserves sortedness for the given inputs (returns true)
func mergePreservesSorted(a: SSet, b: SSet) -> bool =
  let merged = sMerge(a, b);
  isSorted(merged)

-- Prove inclusion-exclusion: |A∪B| + |A∩B| == |A| + |B|
func inclusionExclusion(a: SSet, b: SSet) -> bool =
  let union = sMerge(a, b);
  let inter = sIntersect(a, b);
    (sLength(union) + sLength(inter)) == (sLength(a) + sLength(b))

export func main() -> () ! {IO} {
  let a = SCons(1, SCons(3, SCons(5, SNil)));
  let b = SCons(2, SCons(3, SCons(4, SNil)));

    -- Merge (union with dedup)
  let merged = sMerge(a, b);
  println(toStr(merged));

    -- Intersection
  let intersected = sIntersect(a, b);
  println(toStr(intersected));

    -- Length of merge
  println(show(sLength(merged)));

    -- isSorted on merge result
  println(show(isSorted(merged)));

    -- Proof that merge preserves sortedness
  println(show(mergePreservesSorted(a, b)));

    -- Inclusion-exclusion proof
  println(show(inclusionExclusion(a, b)))
}

