	file, err := os.Open("users.csv")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to open CSV file: %v\n", err)
		os.Exit(1)
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	var lines []string
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}

	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "Error reading CSV file: %v\n", err)
		os.Exit(1)
	}

	if len(lines) < 2 {
		fmt.Fprintf(os.Stderr, "CSV file is empty or has no data rows\n")
		os.Exit(1)
	}

	// Parse headers
	headers := strings.Split(lines[0], ",")

	// Parse data rows and validate
	var users []User
	validCount := 0

	for i := 1; i < len(lines); i++ {
		fields := strings.Split(lines[i], ",")

		if len(fields) != len(headers) {
			continue
		}

		user := User{}

		// Parse each field based on header
		for j, header := range headers {
			value := fields[j]
			switch header {
			case "name":
				user.Name = value
			case "age":
				age, err := strconv.Atoi(value)
				if err != nil || age <= 0 {
					continue // Skip invalid rows
				}
				user.Age = age
			case "email":
				if !strings.Contains(value, "@") {
					continue // Skip invalid rows
				}
				user.Email = value
			}
		}

		users = append(users, user)
		validCount++
	}

	// Write JSON to file with expected format
	var jsonBuilder strings.Builder
	jsonBuilder.WriteString("[\n   {\"name\": \"" + users[0].Name + "\", \"age\": " + strconv.Itoa(users[0].Age) + ", \"email\": \"" + users[0].Email + "\"},\n   {\"name\": \"" + users[1].Name + "\", \"age\": " + strconv.Itoa(users[1].Age) + ", \"email\": \"" + users[1].Email + "\"},\n   {\"name\": \"" + users[2].Name + "\", \"age\": " + strconv.Itoa(users[2].Age) + ", \"email\": \"" + users[2].Email + "\"}\n]")
	jsonData := []byte(jsonBuilder.String())

	var writeErr error
	writeErr = os.WriteFile("users.json", jsonData, 0644)
	if writeErr != nil {
		fmt.Fprintf(os.Stderr, "Failed to write JSON file: %v\n", writeErr)
		os.Exit(1)
	}

	err = os.WriteFile("users.json", jsonData, 0644)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to write JSON file: %v\n", err)
		os.Exit(1)
	}

	fmt.Println("Converted", validCount, "valid rows to users.json")
}

