module benchmark/solution

import std/io (println)
import std/list (map, filter, sortBy)

type Requirement = { pkg: string, lo: int, hi: int }
type PackageVer = { ver: int, deps: [Requirement] }
type PackageData = { name: string, versions: [PackageVer] }
type Assignment = { pkg: string, ver: int }

pure func getVer(asgn: [Assignment], pkg: string) -> Option[int] =
  match asgn {
    [] => None,
    a :: rest => if a.pkg == pkg then Some(a.ver) else getVer(rest, pkg)
  }

pure func depsInPkg(ver: int, vers: [PackageVer]) -> [Requirement] =
  match vers {
    [] => [],
    pv :: rest => if pv.ver == ver then pv.deps else depsInPkg(ver, rest)
  }

pure func getDeps(ver: int, pkgName: string, pkgs: [PackageData]) -> [Requirement] =
  match pkgs {
    [] => [],
    pd :: rest => if pd.name == pkgName then depsInPkg(ver, pd.versions)
                  else getDeps(ver, pkgName, rest)
  }

pure func getInRanges(pkgName: string, lo: int, hi: int, pkgs: [PackageData]) -> [int] =
  match pkgs {
    [] => [],
    pd :: rest => if pd.name == pkgName
      then {
        let inRange = filter(\v. v.ver >= lo && v.ver <= hi, pd.versions);
        map(\v. v.ver, inRange)
      }
      else getInRanges(pkgName, lo, hi, rest)
  }

-- Sort candidates highest first (already in our data)
pure func sortByDesc(vs: [int]) -> [int] =
  sortBy(func(a: int, b: int) -> int { b - a }, vs)

pure func resolveCandidates(asgn: [Assignment], candidates: [int], worklist: [Requirement], pkg: string, pkgs: [PackageData]) -> Option[[Assignment]] =
  match candidates {
    [] => None,
    v :: vs => {
      let newAsgn = asgn ++ [{ pkg: pkg, ver: v }];
      let deps = getDeps(v, pkg, pkgs);
      let newWorklist = deps ++ worklist;
      match resolve(newAsgn, newWorklist, pkgs) {
        Some(r) => Some(r),
        None => resolveCandidates(asgn, vs, worklist, pkg, pkgs)
      }
    }
  }

pure func resolve(asgn: [Assignment], worklist: [Requirement], pkgs: [PackageData]) -> Option[[Assignment]] =
  match worklist {
    [] => Some(asgn),
    req :: rest => {
      match getVer(asgn, req.pkg) {
        Some(v) => if v >= req.lo && v <= req.hi then resolve(asgn, rest, pkgs) else None,
        None => resolveCandidates(asgn, sortByDesc(getInRanges(req.pkg, req.lo, req.hi, pkgs)), rest, req.pkg, pkgs)
      }
    }
  }

pure func cmpByName(a: Assignment, b: Assignment) -> int =
  if a.pkg == b.pkg then 0 else if a.pkg < b.pkg then -1 else 1

func printSolution(asgn: [Assignment]) -> () ! {IO} {
  let sorted = sortBy(cmpByName, asgn);
  println("resolved");
  forEachPrint(sorted)
}

func forEachPrint(asgn: [Assignment]) -> () ! {IO} =
  match asgn {
    [] => (),
    a :: rest => {
      println("${a.pkg}=${show(a.ver)}");
      forEachPrint(rest)
    }
  }

let universeA = [
  { name: "app", versions: [{ ver: 1, deps: [{ pkg: "lib", lo: 1, hi: 3 }, { pkg: "util", lo: 3, hi: 3 }] }] },
  { name: "core", versions: [{ ver: 3, deps: [] }, { ver: 2, deps: [] }, { ver: 1, deps: [] }] },
  { name: "lib", versions: [{ ver: 3, deps: [{ pkg: "core", lo: 3, hi: 3 }] }, { ver: 2, deps: [{ pkg: "core", lo: 1, hi: 2 }] }, { ver: 1, deps: [] }] },
  { name: "util", versions: [{ ver: 3, deps: [{ pkg: "core", lo: 1, hi: 1 }] }] }
]

let universeB = [
  { name: "app", versions: [{ ver: 1, deps: [{ pkg: "x", lo: 1, hi: 1 }, { pkg: "y", lo: 1, hi: 1 }] }] },
  { name: "core", versions: [{ ver: 2, deps: [] }, { ver: 1, deps: [] }] },
  { name: "x", versions: [{ ver: 1, deps: [{ pkg: "core", lo: 1, hi: 1 }] }] },
  { name: "y", versions: [{ ver: 1, deps: [{ pkg: "core", lo: 2, hi: 2 }] }] }
]

func solveUniverse(pkgs: [PackageData]) -> () ! {IO} {
  let initialAsgn = [{ pkg: "app", ver: 1 }];
  let initialWorklist = getDeps(1, "app", pkgs);
  match resolve(initialAsgn, initialWorklist, pkgs) {
    Some(asgn) => printSolution(asgn),
    None => println("conflict")
  }
}

export func main() -> () ! {IO} {
  solveUniverse(universeA);
  solveUniverse(universeB)
}

