  let xml = readDocxContent("sample.docx");
  let parsed = parse(xml);
  let root = match parsed { Ok(r) => r, Err(_) => emptyRoot() };
  let body = firstElem(findAll(root, "w:body"), root);
  let kids = getChildren(body);
  let _ = println(intToStr(listLength(kids)));
  walkAll(kids)
    }

