package main

import "fmt"

// Result type for error propagation
type Result[T any] struct {
	ok  bool
	val T
	err string
}

func Ok[T any](value T) Result[T] {
	return Result[T]{ok: true, val: value}
}

func Err[T any](message string) Result[T] {
	return Result[T]{ok: false, err: message}
}

func (r Result[T]) IsOk() bool {
	return r.ok
}

func (r Result[T]) IsErr() bool {
	return !r.ok
}

func (r Result[T]) Unwrap() T {
	var zero T
	if r.ok {
		return r.val
	}
	return zero
}

func (r Result[T]) Message() string {
	if !r.ok {
		return r.err
	}
	return ""
}

func validateAge(age int) Result[int] {
	if age >= 0 && age <= 150 {
		return Ok(age)
	}
	return Err[int]("Age out of range")
}

func calculateRetirementYears(age int) Result[int] {
	if age < 65 {
		return Ok(65 - age)
	}
	return Err[int]("Already retired")
}

func chainAgeOperations(age int) Result[int] {
	validateResult := validateAge(age)
	if validateResult.IsErr() {
		return Err[int](validateResult.Message())
	}

	validatedAge := validateResult.Unwrap()
	return calculateRetirementYears(validatedAge)
}

func main() {
	testCases := []int{30, 70, -5}

	for _, age := range testCases {
		result := chainAgeOperations(age)

		if result.IsOk() {
			fmt.Printf("Years to retirement: %d\n", result.Unwrap())
		} else {
			fmt.Printf("Error: %s\n", result.Message())
		}
	}
}

