class Result {
  constructor(value, error = null) {
    this.value = value;
    this.error = error;
    this._isOk = error === null;
  }

  static Ok(value) {
    return new Result(value);
  }

  static Err(message) {
    return new Result(null, message);
  }

  isOk() {
    return this._isOk;
  }

  isErr() {
    return !this._isOk;
  }

  unwrap() {
    if (this._isOk) {
      return this.value;
    }
    throw new Error(this.error);
  }

  match(okFn, errFn) {
    if (this._isOk) {
      return okFn(this.value);
    }
    return errFn(this.error);
  }
}

function validateAge(age) {
  if (age >= 0 && age <= 150) {
    return Result.Ok(age);
  }
  return Result.Err('Age out of range');
}

function calculateRetirementYears(age) {
  if (age < 65) {
    return Result.Ok(65 - age);
  }
  return Result.Err('Already retired');
}

function chainOperations(age) {
  const validated = validateAge(age);

  return validated.match((validAge) => {
    return calculateRetirementYears(validAge);
  }, (error) => {
    return Result.Err(error);
  });
}

function main() {
  const testCases = [30, 70, -5];

  for (const age of testCases) {
    const result = chainOperations(age);

    result.match(
      (value) => console.log(`Years to retirement: ${value}`),
      (error) => console.log(`Error: ${error}`)
    );
  }
}

main();

