function bfs(startNode) {
  const visited = new Set();
  const queue = [];
  const result = [];

  // Initialize
  enqueue(startNode, queue);
  visited.add(startNode);

  // Process queue (add to end, remove from front - standard BFS pattern)
  while (queue.length > 0) {
    const current = queue.shift(); // remove from front
    result.push(current);

    // Visit all neighbors
    const neighbors = graph.get(current) || [];
    for (const neighbor of neighbors) {
      if (!contains(neighbor, visited)) {
        visited.add(neighbor);
        enqueue(neighbor, queue);
      }
    }
  }

  return result;
}

