import std/list (sortBy, nth, length)
import std/io (println)
import std/option (Some, None)

pure func cmpInt(a: int, b: int) -> int = a - b

pure func median(xs: [int]) -> int {
  let sorted = sortBy(cmpInt, xs);
  let n = length(sorted);
  if n == 0 then 0
  else match n % 2 == 0 {
    true => {
      let idx = (n / 2) - 1;
      match nth(sorted, idx) {
        Some(v) => v,
        None => 0
      }
    },
    false => {
      let idx = n / 2;
      match nth(sorted, idx) {
        Some(v) => v,
        None => 0
      }
    }
  }
}

export func main() -> () ! {IO} {
  println(show(median([7, 2, 5, 1, 9, 4, 8])));
  println(show(median([10, 20, 30, 40])))
}

