module benchmark/solution

-- Define Term type for lambda calculus
type Term = TVar(string) | TLam(string, Term) | TApp(Term, Term)

-- Substitute all free occurrences of var with replacement in term
pure func subst(term: Term, var: string, replacement: Term) -> Term {
  match term {
    TVar(x) => if x == var then replacement else TVar(x),
    TLam(n, body) => if n == var then TLam(n, body) else TLam(n, subst(body, var, replacement)),
    TApp(f, a) => TApp(subst(f, var, replacement), subst(a, var, replacement))
  }
}

-- Evaluate using call-by-value
pure func eval(term: Term) -> Term {
  match term {
    TVar(x) => TVar(x),
    TLam(n, body) => TLam(n, body),
    TApp(f, a) => {
      let fv = eval(f);
      let av = eval(a);
      match fv {
        TLam(n, b) => subst(b, n, av),
        _ => fv
      }
    }
  }
}

export func main() -> () ! {IO} {
  let one = TVar("1");
  let two = TVar("2");
  let body = TLam("y", TVar("x"));
  let abs_y = TLam("x", body);
  let app_y = TApp(abs_y, one);
  let full_term = TApp(app_y, two);
  let result = eval(full_term);
  println(match result { TVar(s) => s })
}

