package main

import "fmt"

// Term represents a lambda calculus term
type Term interface {
	isTerm()
}

// TVar is a variable term
type TVar struct {
	Name string
}

func (TVar) isTerm() {}

// TLam is a lambda abstraction: λx.body
type TLam struct {
	Name string
	Body Term
}

func (TLam) isTerm() {}

// TApp is an application: f x
type TApp struct {
	Fun Term
	Arg Term
}

func (TApp) isTerm() {}

// subst substitutes var with replacement in term
func subst(term Term, varName string, replacement Term) Term {
	switch t := term.(type) {
	case TVar:
		if t.Name == varName {
			return replacement
		}
		return t
	case TLam:
		// Don't substitute under a lambda that binds the same variable
		if t.Name == varName {
			return t
		}
		newBody := subst(t.Body, varName, replacement)
		return TLam{Name: t.Name, Body: newBody}
	case TApp:
		return TApp{Fun: subst(t.Fun, varName, replacement), Arg: subst(t.Arg, varName, replacement)}
	default:
		return term
	}
}

func eval(term Term) Term {
	switch t := term.(type) {
	case TVar:
		// Variables evaluate to themselves
		return t
	case TLam:
		// Lambda is a value
		return t
	case TApp:
		// Evaluate the function and argument, then apply if the function is a lambda
		evalFun := eval(t.Fun)
		evalArg := eval(t.Arg)

		if lam, ok := evalFun.(TLam); ok {
			// Substitution: replace all occurrences of lam.Name in lam.Body with evalArg
			result := subst(lam.Body, lam.Name, evalArg)
			return eval(result)
		}
		// Not a lambda, return the application as-is (value form)
		return t
	default:
		return t
	}
}

func main() {
	// Build the term: (λx. λy. x) 1 2
	// Inner: (λx. λy. x) 1
	// Outer: (...) 2

	kapp := TLam{Name: "x", Body: TLam{Name: "y", Body: TVar{"x"}}}

	arg1 := TVar{"1"}
	arg2 := TVar{"2"}

	app1 := TApp{Fun: kapp, Arg: arg1}
	result := eval(TApp{Fun: app1, Arg: arg2})

	fmt.Println(result.(TVar).Name)
}

