// Term type definition using classes
class TVar {
  constructor(name) {
    this.name = name;
    this.type = 'TVar';
  }

  toString() {
    return this.name;
  }
}

class TLam {
  constructor(param, body) {
    this.param = param;
    this.body = body;
    this.type = 'TLam';
  }

  toString() {
    return `λ${this.param}.${this.body}`;
  }
}

class TApp {
  constructor(func, arg) {
    this.func = func;
    this.arg = arg;
    this.type = 'TApp';
  }

  toString() {
    return `(${this.func} ${this.arg})`;
  }
}

// Check if a term is a value (variable or lambda)
function isValue(term) {
  return term.type === 'TVar' || term.type === 'TLam';
}

// Free variables in a term
function freeVars(term) {
  switch (term.type) {
    case 'TVar':
      return new Set([term.name]);
    case 'TLam':
      const bodyFree = freeVars(term.body);
      bodyFree.delete(term.param);
      return bodyFree;
    case 'TApp':
      const leftFree = freeVars(term.func);
      const rightFree = freeVars(term.arg);
      const union = new Set([...leftFree, ...rightFree]);
      return union;
    default:
      return new Set();
  }
}

// Substitute var with replacement in term (alpha conversion to avoid capture)
function subst(term, varName, replacement) {
  switch (term.type) {
    case 'TVar':
      if (term.name === varName) {
        return replacement;
      }
      return term;

    case 'TLam':
      // If the bound variable is the same as what we're substituting, don't substitute in body
      if (term.param === varName) {
        return term;
      }

      // Check for variable capture
      const replacementFree = freeVars(replacement);
      if (replacementFree.has(term.param)) {
        // Need to rename the bound variable to avoid capture
        const freshVar = findFreshVar(term.param, term.body, replacementFree);
        const renamedBody = subst(term.body, term.param, new TVar(freshVar));
        return new TLam(freshVar, subst(renamedBody, varName, replacement));
      }

      return new TLam(term.param, subst(term.body, varName, replacement));

    case 'TApp':
      return new TApp(
        subst(term.func, varName, replacement),
        subst(term.arg, varName, replacement)
      );

    default:
      throw new Error(`Unknown term type: ${term.type}`);
  }
}

// Find a fresh variable name (not in free vars set or equal to current param names)
function findFreshVar(currentParam, body, forbidden) {
  let counter = 0;
  let freshVar;

  do {
    freshVar = `${currentParam}$${counter}`;
    counter++;
  } while (forbidden.has(freshVar));

  return freshVar;
}

// Evaluate term using call-by-value
function evalTerm(term) {
  switch (term.type) {
    case 'TVar':
      // Variables evaluate to themselves
      return term;

    case 'TLam':
      // lambdas are values
      return term;

    case 'TApp':
      // Evaluate function and argument
      const evaluatedFunc = evalTerm(term.func);

      if (evaluatedFunc.type === 'TLam') {
        // Apply the lambda by substituting and evaluating
        const evaluatedArg = evalTerm(term.arg);
        const substituted = subst(evaluatedFunc.body, evaluatedFunc.param, evaluatedArg);
        return evalTerm(substituted);
      } else if (evaluatedFunc.type === 'TApp') {
        // Partially applied function - evaluate further
        const newApp = new TApp(
          evaluatedFunc.func,
          new TApp(evaluatedFunc.arg, term.arg)
        );
        return evalTerm(newApp);
      } else {
        throw new Error('Cannot apply non-lambda: ' + evaluatedFunc.toString());
      }

    default:
      throw new Error(`Unknown term type: ${term.type}`);
  }
}

// Convert result to string representation for output
function toOutputString(term) {
  switch (term.type) {
    case 'TVar':
      return term.name;
    case 'TLam':
      return `λ${term.param}.${toOutputString(term.body)}`;
    case 'TApp':
      const funcStr = term.func.type === 'TApp' || term.func.type === 'TVar' 
        ? toOutputString(term.func)
        : `(${toOutputString(term.func)})`;
      const argStr = term.arg.type === 'TApp' || term.arg.type === 'TVar'
        ? toOutputString(term.arg)
        : `(${toOutputString(term.arg)})`;
      return `${funcStr}${argStr}`;
    default:
      return String(term);
  }
}

// Main function - entry point
function main() {
  // Build the expression (λx. λy. x) 1 2
  // As AST: TApp(TApp(TLam("x", TLam("y", TVar("x"))), TVar("1")), TVar("2"))

  const innerLambda = new TLam('y', new TVar('x'));
  const outerLambda = new TLam('x', innerLambda);
  const arg1 = new TVar('1');
  const arg2 = new TVar('2');

  // Build ((λx. λy. x) 1) 2
  const partialApp = new TApp(outerLambda, arg1);
  const fullApp = new TApp(partialApp, arg2);

  // Evaluate the expression
  const result = evalTerm(fullApp);

  // Output the result
  console.log(toOutputString(result));
}

// Run main
main();

