from dataclasses import dataclass
from typing import NamedTuple


class Term:
    pass


class TVar(Term):
    def __init__(self, name: str):
        self.name = name

    def __repr__(self):
        return f'TVar("{self.name}")'


class TLam(Term):
    def __init__(self, param: str, body: Term):
        self.param = param
        self.body = body

    def __repr__(self):
        return f'TLam("{self.param}", {self.body!r})'


class TApp(Term):
    def __init__(self, f: Term, arg: Term):
        self.f = f
        self.arg = arg

    def __repr__(self):
        return f'TApp({self.f!r}, {self.arg!r})'


def subst(term: Term, var: str, replacement: Term) -> Term:
    if isinstance(term, TVar):
        if term.name == var:
            return replacement
        return term
    if isinstance(term, TLam):
        return TLam(term.param, subst(term.body, var, replacement))
    if isinstance(term, TApp):
        return TApp(subst(term.f, var, replacement),
                    subst(term.arg, var, replacement))
    raise ValueError(f"Unknown term: {term}")


def eval(term: Term) -> Term:
    if isinstance(term, TVar):
        return term
    if isinstance(term, TLam):
        return term
    if isinstance(term, TApp):
        f = eval(term.f)
        arg = eval(term.arg)
        if isinstance(f, TLam):
            return eval(subst(f.body, f.param, arg))
        return TApp(f, arg)
    raise ValueError(f"Unknown term: {term}")


def main():
    # (λx. λy. x) 1 2
    expr = TApp(TApp(TLam("x", TLam("y", TVar("x"))), TVar("1")), TVar("2"))
    result = eval(expr)
    if isinstance(result, TVar):
        print(result.name)
    else:
        print(repr(result))


if __name__ == "__main__":
    main()

