import std/io (println)
import std/list (map, foldl)
import std/option (None, isNone, Some)

type Milestone = {
  name: string,
  origDeadline: int,
  origPrice: int,
  effectiveDeadline: int,
  effectivePrice: int,
  deliveryDay: Option[int],
  paymentDay: Option[int]
}

func computeDeliveryPenalty(lateDays: int) -> int {
  let p = lateDays * 200;
  if p > 4000 then 4000 else p
}

func computeInterest(price: int, daysLate: int) -> int {
  let periods = daysLate / 10;
     (price * periods) / 100
}

func updateMilestone(m: Milestone, ev: Event) -> Milestone {
  match ev {
    Deliver(name, day) => if m.name == name then {m | deliveryDay: Some(day)} else m,
    Amendment(name, price) => if m.name == name then {m | effectivePrice: price} else m,
    ForceMajeure(d1, d2) => if isNone(m.deliveryDay) && m.effectiveDeadline >= d1 && m.effectiveDeadline <= d2 then {m | effectiveDeadline: m.effectiveDeadline + (d2 - d1 + 1)} else m,
    Payment(name, day) => if m.name == name then {m | paymentDay: Some(day)} else m
  }
}

type Event =
  Deliver(string, int)
    | Amendment(string, int)
    | ForceMajeure(int, int)
    | Payment(string, int)

let m1Init = {name: "M1", origDeadline: 10, origPrice: 10000, effectiveDeadline: 10, effectivePrice: 10000, deliveryDay: None, paymentDay: None}
let m2Init = {name: "M2", origDeadline: 40, origPrice: 20000, effectiveDeadline: 40, effectivePrice: 20000, deliveryDay: None, paymentDay: None}
let m3Init = {name: "M3", origDeadline: 70, origPrice: 15000, effectiveDeadline: 70, effectivePrice: 15000, deliveryDay: None, paymentDay: None}

let events = [
  Deliver("M1", 8),
  Amendment("M2", 22000),
  ForceMajeure(38, 44),
  Payment("M1", 41),
  Payment("M2", 74)
]

let m1Final = foldl(updateMilestone, m1Init, events)
let m2Final = foldl(updateMilestone, m2Init, events)
let m3Final = foldl(updateMilestone, m3Init, events)

export func main() -> () ! {IO} {
  let terminationDay = 96;

  let m1LateDays = 0;
  let m1DeliveryPenalty = computeDeliveryPenalty(m1LateDays);

  let m2Deadline = m2Final.effectiveDeadline;
  let m2LateDays = 50 - m2Deadline;
  let m2DeliveryPenalty = computeDeliveryPenalty(m2LateDays);

  let m3LateDays = (terminationDay - 1) - (m3Final.effectiveDeadline + 1) + 1;
  let m3DeliveryPenalty = computeDeliveryPenalty(m3LateDays);

  let m1PaymentDue = 8 + 10;
  let m1DaysLate = 41 - m1PaymentDue;
  let m1Interest = computeInterest(10000, m1DaysLate);

  let m2PaymentDue = 50 + 10;
  let m2DaysLate = 74 - m2PaymentDue;
  let m2Interest = computeInterest(22000, m2DaysLate);

  let vendorOwes = m1DeliveryPenalty + m2DeliveryPenalty + m3DeliveryPenalty;
  let clientOwes = m2Interest;

  let netDiff = vendorOwes - clientOwes;

  println("M1 effective: deadline=${m1Final.effectiveDeadline} price=${m1Final.effectivePrice}");
  println("M2 effective: deadline=${m2Final.effectiveDeadline} price=${m2Final.effectivePrice}");
  println("M3 effective: deadline=${m3Final.effectiveDeadline} price=${m3Final.effectivePrice}");

  println("M1 delivery: DELIVERED day=8 late=${m1LateDays} penalty=${m1DeliveryPenalty}");
  println("M1 payment: PAID day=41 late=${m1DaysLate} interest=${m1Interest}");
  println("M1 payment breach: WAIVED");

