import std/option (Option, Some, None)

type Op = Get(int) | Put(int, int)

pure func findEntry(entries: [{key: int, value: int, count: int, lastUsed: int}], k: int) -> Option[{key: int, value: int, count: int, lastUsed: int}] =
  match entries {
    [] => None,
    e :: rest => if e.key == k then Some(e) else findEntry(rest, k)
  }

pure func updateForGet(entries: [{key: int, value: int, count: int, lastUsed: int}], k: int, ts: int) -> [{key: int, value: int, count: int, lastUsed: int}] =
  map(\ent. if ent.key == k then {ent | count: ent.count + 1, lastUsed: ts} else ent, entries)

pure func updateForPut(entries: [{key: int, value: int, count: int, lastUsed: int}], k: int, v: int, ts: int) -> [{key: int, value: int, count: int, lastUsed: int}] =
  map(\ent. if ent.key == k then {ent | value: v, count: ent.count + 1, lastUsed: ts} else ent, entries)

pure func cmpEvict(a: {key: int, value: int, count: int, lastUsed: int}, b: {key: int, value: int, count: int, lastUsed: int}) -> int ! {} =
  if a.count != b.count then a.count - b.count else a.lastUsed - b.lastUsed

pure func evictLFU(entries: [{key: int, value: int, count: int, lastUsed: int}]) -> [{key: int, value: int, count: int, lastUsed: int}] =
  let sorted = sortBy(cmpEvict, entries);
  match sorted {
     _ :: rest => rest,
     [] => []
  }

func processOp(entries: [{key: int, value: int, count: int, lastUsed: int}], op: Op, ts: int) -> [Entry] ! {IO} =
  match op {
    Get(k) => match findEntry(entries, k) {
      Some(e) => {
        println(show(e.value));
        updateForGet(entries, k, ts)
      },
      None => {
        println("-1");
        entries
      }
    },
    Put(k, v) => match findEntry(entries, k) {
      Some(_) => updateForPut(entries, k, v, ts),
      None =>
        if length(entries) >= 3 then
          evictLFU(entries) ++ [{key: k, value: v, count: 1, lastUsed: ts}]
        else
          entries ++ [{key: k, value: v, count: 1, lastUsed: ts}]
    }
  }

func processAll(entries: [Entry], ops: [Op], ts: int) -> [Entry] ! {IO} =
  match ops {
    [] => entries,
    op :: rest => processAll(processOp(entries, op, ts), rest, ts + 1)
  }

type Entry = {key: int, value: int, count: int, lastUsed: int}

func formatCache(entries: [Entry]) -> string =
  let sortedBy = sortBy(func(a: {key: int}, b: {key: int}) -> int { a.key - b.key }, entries);
  join(",", map(\ent. "${ent.key}=${ent.value}", sortedBy))

export func main() -> () ! {IO} {
  let ops: [Op] = [
    Put(1, 10),
    Put(2, 20), Put(3, 30),
    Get(1),
    Put(4, 40),
    Put(5, 50),
    Get(3), Get(4), Get(5), Get(1),
    Put(4, 44),
    Put(6, 60),
    Get(5), Get(6), Get(6),
    Put(7, 70),
    Get(1), Get(4),
    Put(8, 80),
    Get(7)
   ];
  let finalCache = processAll([], ops, 1);
  println("cache: ${formatCache(finalCache)}")
}

