  match xs {
     [] => [],
    head :: tail => f(head) :: mapList(f, tail)
  }

-- Recursive foldl: fold from left with accumulator
pure func foldlList(f: (int, int) -> int, acc: int, xs: [int]) -> int =
  match xs {
     [] => acc,
    head :: tail => foldlList(f, f(acc, head), tail)
  }

