pure func merge(xs: [int], ys: [int]) -> [int] =
  match xs {
    [] => ys,
    x :: rest_x => match ys {
      [] => xs,
      y :: rest_y => if x <= y then x :: merge(rest_x, ys) else y :: merge(xs, rest_y)
      }
     }

-- Split helper: builds two lists by alternating elements
pure func splitHelper(xs: [int], left_acc: [int], right_acc: [int]) -> ([int], [int]) =
  match xs {
    [] => (left_acc, right_acc),
    x :: rest => splitHelper(rest, right_acc ++ [x], left_acc)
    }

-- Split a list into two halves
pure func split(xs: [int]) -> ([int], [int]) =
  match xs {
    [] => ([], []),
    [x] => ([x], []),
     _ => splitHelper(xs, [], [])
   }

-- Get first element of pair via pattern matching
pure func firstPair(t: ([int], [int])) -> [int] =
  match t {
    (left, _) => left
  }

-- Get second element of pair via pattern matching
pure func secondPair(t: ([int], [int])) -> [int] =
  match t {
    (_, right) => right
  }

-- Merge sort: recursively sorts a list
pure func mergeSort(xs: [int]) -> [int] =
  match xs {
     [] => [],
     [x] => xs,
     _ => {
       let paired = split(xs);
       let left = firstPair(paired);
       let right = secondPair(paired);
       let sorted_left = mergeSort(left);
       let sorted_right = mergeSort(right);
       merge(sorted_left, sorted_right)
       }
    }

