package main

import "fmt"

// merge merges two sorted slices into one sorted slice
func merge(xs, ys []int) []int {
	result := make([]int, 0, len(xs)+len(ys))
	i, j := 0, 0
	for i < len(xs) && j < len(ys) {
		if xs[i] <= ys[j] {
			result = append(result, xs[i])
			i++
		} else {
			result = append(result, ys[j])
			j++
		}
	}
	for i < len(xs) {
		result = append(result, xs[i])
		i++
	}
	for j < len(ys) {
		result = append(result, ys[j])
		j++
	}
	return result
}

// split splits a slice into two halves
func split(xs []int) ([]int, []int) {
	mid := len(xs) / 2
	if mid == 0 {
		return xs, nil
	}
	return xs[:mid], xs[mid:]
}

// mergeSort recursively sorts a slice using merge sort algorithm
func mergeSort(xs []int) []int {
	if len(xs) <= 1 {
		return xs
	}
	left, right := split(xs)
	return merge(mergeSort(left), mergeSort(right))
}

