import std/option (Option, Some, None)

// AST definition for mini language expressions
type Expr = Num(int) | Var(string) | Add(Expr, Expr) | Mul(Expr, Expr) | Let(string, Expr, Expr)

// Environment is a list of (name, value) pairs - each binding is { name: string, val: int }
type Env = [{ name: string, val: int }]

// Lookup variable in environment - returns None if not found
pure func lookup(name: string, env: Env) -> Option[int] =
  match env {
     [] => None,
    binding :: rest => if binding.name == name then Some(binding.val) else lookup(name, rest)
   }

// Evaluate expression in environment - assumes all vars are defined (safe for this task)
pure func eval(expr: Expr, env: Env) -> int =
  match expr {
     Num(n) => n,
     Var(v) => match lookup(v, env) {
       Some(val) => val,
       None => 0
     },
     Add(e1, e2) => eval(e1, env) + eval(e2, env),
     Mul(e1, e2) => eval(e1, env) * eval(e2, env),
     Let(name, e1, e2) => {
       let v = eval(e1, env);
       let newEnv = { name: name, val: v } :: env;
       eval(e2, newEnv)
     }
   }

// Build the program AST: let x = 5 in (let y = x + 3 in x * y)
let program = Let("x", Num(5), Let("y", Add(Var("x"), Num(3)), Mul(Var("x"), Var("y"))))

// Evaluate and print the result
export func main() -> () ! {IO} {
  let env: Env = [];
  let result = eval(program, env);
  println(show(result))
}

