package main

import "fmt"

// Environment is a list of (name, value) pairs
type Env []EnvEntry

type EnvEntry struct {
	Name  string
	Value int
}

// Expr interface for the AST
type Expr interface {
	evaluate(e Env) int
}

// Num represents an integer literal
type Num struct{ Value int }

func (n Num) evaluate(e Env) int { return n.Value }

// Var represents a variable reference
type Var string

func (v Var) evaluate(env Env) int { return lookup(string(v), env) }

// Add represents addition of two expressions
type Add struct {
	Left  Expr
	Right Expr
}

func (a Add) evaluate(e Env) int {
	return a.Left.evaluate(e) + a.Right.evaluate(e)
}

// Mul represents multiplication of two expressions
type Mul struct {
	Left  Expr
	Right Expr
}

func (m Mul) evaluate(e Env) int {
	return m.Left.evaluate(e) * m.Right.evaluate(e)
}

// Let represents let binding: let name = expr1 in expr2
type Let struct {
	Name    string
	Expr1   Expr
	Expr2   Expr
}

func (l Let) evaluate(e Env) int {
	v := l.Expr1.evaluate(e)
	newEnv := append(e, EnvEntry{Name: l.Name, Value: v})
	return l.Expr2.evaluate(newEnv)
}

// lookup finds a variable's value in the environment
func lookup(name string, env Env) int {
	for i := len(env) - 1; i >= 0; i-- {
		if env[i].Name == name {
			return env[i].Value
		}
	}
	panic("undefined variable: " + name)
}

func main() {
	program := Let{"x", Num{5}, Let{"y", Add{Var("x"), Num{3}}, Mul{Var("x"), Var("y")}}}
	result := program.evaluate(nil)
	fmt.Println(result)
}

