    } else if (expr instanceof Var) {
        return lookup(expr.name, env);
    } else if (expr instanceof Add) {
        const left = evalExpr(expr.left, env);
        const right = evalExpr(expr.right, env);
        return left + right;
    } else if (expr instanceof Mul) {
        const left = evalExpr(expr.left, env);
        const right = evalExpr(expr.right, env);
        return left * right;
    } else if (expr instanceof Let) {
        const value = evalExpr(expr.scope, env);
        const newEnv = [...env, [expr.name, value]];
        return evalExpr(expr.body, newEnv);
    } else {
        throw new Error(`Unknown expression type`);
    }
}

function main() {
    const program = new Let(
        "x",
        new Num(5),
        new Let(
            "y",
            new Add(new Var("x"), new Num(3)),
            new Mul(new Var("x"), new Var("y"))
        )
    );

    const result = evalExpr(program, []);
    console.log(result);
}

main();

