from dataclasses import dataclass
from typing import List, Tuple


class Expr:
    pass


@dataclass
class Num(Expr):
    value: int


@dataclass
class Var(Expr):
    name: str


@dataclass
class Add(Expr):
    left: Expr
    right: Expr


@dataclass
class Mul(Expr):
    left: Expr
    right: Expr


@dataclass
class Let(Expr):
    name: str
    value: Expr
    body: Expr


Env = List[Tuple[str, int]]


def lookup(name: str, env: Env) -> int:
    for n, v in env:
        if n == name:
            return v
    raise NameError(f"unbound variable: {name}")


def ev(expr: Expr, env: Env) -> int:
    match expr:
        case Num(v):
            return v
        case Var(n):
            return lookup(n, env)
        case Add(l, r):
            return ev(l, env) + ev(r, env)
        case Mul(l, r):
            return ev(l, env) * ev(r, env)
        case Let(n, e1, e2):
            v = ev(e1, env)
            return ev(e2, [(n, v), *env])
        case _:
            raise RuntimeError("unknown expression")


def main() -> None:
    program = Let(
        "x",
        Num(5),
        Let(
            "y",
            Add(Var("x"), Num(3)),
            Mul(Var("x"), Var("y")),
        ),
    )
    print(ev(program, []))


if __name__ == "__main__":
    main()

