module benchmark/solution

import std/io (println)
import std/string (chars, concat)
import std/list (map, reverse)

type Parse = { out: string, rest: [string] }

pure func isDigit(c: string) -> bool = (c >= "0") && (c <= "9")

func collectDigits(rest: [string], cur: string) -> Parse =
  match rest {
    [] => { out: cur, rest: [] }
    (c :: r) =>
      if isDigit(c)
        then collectDigits(r, concat([cur, c]))
        else { out: cur, rest: rest }
  }

func tokenize(s: string) -> [string] = buildTokens(chars(s), [])

func buildTokens(cs: [string], acc: [string]) -> [string] =
  match cs {
    [] => reverse(acc)
    (c :: rest) =>
      if isDigit(c)
        then {
          let d = collectDigits(rest, c);
          buildTokens(d.rest, d.out :: acc)
        }
        else buildTokens(rest, c :: acc)
  }

pure func binPrec(op: string) -> int =
  match op {
    "+" => 1,
    "-" => 1,
    "*" => 2,
    "/" => 2,
    "^" => 4,
    _ => 0
  }

func parseExp(minPrec: int, toks: [string]) -> Parse = {
  let first = parseNud(toks);
  led(first, minPrec)
}

func parseNud(toks: [string]) -> Parse =
  match toks {
    [] => { out: "", rest: [] }
    ("(" :: rest) => {
      let inner = parseExp(1, rest);
      match inner.rest {
        (")" :: r2) => { out: inner.out, rest: r2 },
        _ => { out: inner.out, rest: inner.rest }
      }
    }
    ("-" :: rest) => {
      let operand = parseExp(3, rest);
      { out: "(-${operand.out})", rest: operand.rest }
    }
    (c :: rest) => { out: c, rest: rest }
  }

func led(acc: Parse, minPrec: int) -> Parse =
  match acc.rest {
    (op :: rest) => {
      let p = binPrec(op);
      if p >= 1 && p >= minPrec
        then {
          let newMin = if op == "^" then 4 else (p + 1);
          let rhs = parseExp(newMin, rest);
          led({ out: "(${acc.out}${op}${rhs.out})", rest: rhs.rest }, minPrec)
        }
        else acc
    }
    [] => acc
  }

func parseOne(s: string) -> string {
  let tok = tokenize(s);
  let p = parseExp(1, tok);
  p.out
}

func printResults(xs: [string]) -> () ! {IO} =
  match xs {
    [] => (),
    (x :: rest) => { println(x); printResults(rest) }
  }

export func main() -> () ! {IO} {
  let exprs = ["-2^2", "2^3^2", "8-4-2", "2^-3*4", "--5+1", "-2^-2^3", "(1+2)*-3", "100-10*-2^2"];
  let results = map(parseOne, exprs);
  printResults(results)
}

