	"fmt"
	"sort"
)

func top3(xs []any) []any {
	sorted := make([]any, len(xs))
	copy(sorted, xs)

	sort.Slice(sorted, func(i, j int) bool {
		return compareLess(sorted[i], sorted[j])
	})

	result := make([]any, 0, 3)
	for i := 0; i < len(sorted) && i < 3; i++ {
		result = append(result, sorted[i])
	}

	return result
}

func compareLess(a, b any) bool {
	switch va := a.(type) {
	case int:
		vb := b.(int)
		return va > vb
	case string:
		vb := b.(string)
		return va > vb
	default:
		return false
	}
}

