from __future__ import annotations

import sys
from typing import Callable, TypeVar


class Declassify:
    """Marker for functions that intentionally change a value's label."""


F = TypeVar("F", bound=Callable[..., object])


def declassifies(*effects: type) -> Callable[[F], F]:
    def decorate(function: F) -> F:
        setattr(function, "__effects__", frozenset(effects))
        return function

    return decorate


class LabelledString(str):
    def __new__(cls, value: str, label: str) -> LabelledString:
        instance = super().__new__(cls, value)
        instance.label = label
        return instance


@declassifies(Declassify)
def sanitizeBody(email_body: str) -> LabelledString:
    if isinstance(email_body, LabelledString) and email_body.label != "email":
        raise ValueError("sanitizeBody requires an email-labelled string")
    return LabelledString("[sanitized]", "sanitized")


class SendAction:
    def __init__(self, recipient: str, body: LabelledString) -> None:
        self.recipient = recipient
        self.body = body


@declassifies(Declassify)
def safeForward(raw_body: str, recipient: str) -> SendAction:
    if not recipient.endswith("@company.com"):
        raise ValueError("recipient must end with @company.com")

    email_body = LabelledString(raw_body, "email")
    sanitized_body = sanitizeBody(email_body)
    return SendAction(recipient, sanitized_body)


def main() -> None:
    lines = sys.stdin.read().splitlines()
    raw_body = "\n".join(lines[:-1]) if len(lines) >= 2 else ""
    recipient = lines[-1] if lines else "user@example.com"

    try:
        action = safeForward(raw_body, recipient)
    except ValueError:
        print(0)
        return

    print(1 if action.recipient.endswith("@company.com") else 0)


