import std/list (foldl)

-- Enum for color
type Color = Red | Black deriving (Eq)

-- Red-black tree: Empty or Node with Color, left subtree, value, right subtree
type RBTree = Empty | Node(Color, RBTree, int, RBTree)

-- Balance function to fix red-red violations  
pure func balance(color: Color, left: RBTree, value: int, right: RBTree) -> RBTree {
  match (color, left, right) {
    (Red, Node(Red, a, x, b), Node(Black, c, y, d)) =>
      Node(Red, Node(Black, a, x, b), value, Node(Black, c, y, d)),
     _ => Node(color, left, value, right)
  }
}

-- Insertion function for red-black tree
pure func insert(x: int, tree: RBTree) -> RBTree {
  match tree {
    Empty => Node(Red, Empty, x, Empty),
    Node(col, left, value, right) =>
      if x < value then balance(col, insert(x, left), value, right)
      else if x > value then balance(col, left, value, insert(x, right))
      else tree
  }
}

-- Re-color root to black after insertion
pure func reBlack(tree: RBTree) -> RBTree {
  match tree {
    Empty => Empty,
    Node(_, left, value, right) => Node(Black, left, value, right)
  }
}

-- In-order traversal: Left, Root, Right - uses ++ for list concatenation
pure func inorder(tree: RBTree) -> [int] {
  match tree {
    Empty => [],
    Node(_, left, value, right) => inorder(left) ++ [value] ++ inorder(right)
  }
}

-- Build initial empty tree and insert values sequentially  
func build_tree(values: [int]) -> RBTree = foldl(\acc x. insert(x, acc), Empty, values)

export func main() -> () ! {IO} {
  let values = [7, 3, 18, 10, 22, 8, 11, 26];
  let tree = build_tree(values);
  let sorted = inorder(tree);
  println(show(sorted))
