package main

import (
	"fmt"
	"strings"
)

// Color represents the color of a red-black tree node
type Color int

const (
	Red   Color = iota
	Black Color = iota
)

// RBTree represents a node in the red-black tree
type RBTree struct {
	c     Color
	key   int
	left    *RBTree
	right   *RBTree
}

// isRed checks if a node is Red (returns false for nil nodes)
func isRed(t *RBTree) bool {
	if t == nil {
		return false
	}
	return t.c == Red
}

// newNode creates a new red node with the given key and no children
func newNode(k int) *RBTree {
	return &RBTree{c: Red, key: k, left: nil, right: nil}
}

// rotateLeft performs a left rotation around node t
func rotateLeft(t *RBTree) *RBTree {
	if t == nil || t.right == nil {
		return t
	}
	x := t.right
	t.right = x.left
	x.left = t
	x.c = t.c // x takes the parent's color after rotation
	return x
}

// rotateRight performs a right rotation around node t
func rotateRight(t *RBTree) *RBTree {
	if t == nil || t.left == nil {
		return t
	}
	x := t.left
	t.left = x.right
	x.right = t
	x.c = t.c // x takes the parent's color after rotation
	return x
}

// balance fixes red-red violations in the red-black tree
// Pattern matches on the 4 rotation cases (left-left, left-right, right-left, right-right)
func balance(t *RBTree) *RBTree {
	// Left-left case: black parent with red left child that has red left grandchild -> right rotate
	if !isRed(t) && isRed(t.left) && isRed(t.left.left) {
		t = rotateRight(t)
		t.left.c = Black
	} else if !isRed(t) && isRed(t.left) && isRed(t.left.right) {
		// Left-right case: black parent with red left child that has red right grandchild
		t.left = rotateLeft(t.left)
		t = rotateRight(t)
		t.left.c = Black
	} else if !isRed(t) && isRed(t.right) && isRed(t.right.right) {
		// Right-right case: black parent with red right child that has red right grandchild -> left rotate
		t = rotateLeft(t)
		t.right.c = Black
	} else if !isRed(t) && isRed(t.right) && isRed(t.right.left) {
		// Right-left case: black parent with red right child that has red left grandchild
		t.right = rotateRight(t.right)
		t = rotateLeft(t)
		t.right.c = Black
	}
	return t
}

// insert inserts a value into the red-black tree and returns the new root
func insert(t *RBTree, key int) *RBTree {
	if t == nil {
		return newNode(key)
	}

	// Copy all fields including subtrees to maintain immutability/structural sharing
	result := &RBTree{c: t.c, key: t.key, left: t.left, right: t.right}

	if key < t.key {
		result.left = insert(t.left, key)
	} else if key > t.key {
		result.right = insert(t.right, key)
	}

	// Balance the tree to maintain red-black properties
	return balance(result)
}

// countNodes counts the number of nodes in the tree (for debugging/verification)
func countNodes(t *RBTree) int {
	if t == nil {
		return 0
	}
	return 1 + countNodes(t.left) + countNodes(t.right)
}

// inorder performs an inorder traversal of the tree and returns sorted values
func inorder(t *RBTree, result *[]int) {
	if t == nil {
		return
	}
	inorder(t.left, result)
	*result = append(*result, t.key)
	inorder(t.right, result)
}

func main() {
	// Values to insert: [7, 3, 18, 10, 22, 8, 11, 26]
	values := []int{7, 3, 18, 10, 22, 8, 11, 26}

	// Start with an empty tree and insert all values
	tree := (*RBTree)(nil)
	for _, v := range values {
		tree = insert(tree, v)
	}

	// Get the inorder traversal (sorted order)
	result := []int{}
	inorder(tree, &result)

	// Build output string "[3, 7, 8, 10, 11, 18, 22, 26]"
	var parts []string
	for _, v := range result {
		parts = append(parts, fmt.Sprintf("%d", v))
	}
	fmt.Println("[" + strings.Join(parts, ", ") + "]")
}

