const NODE_EMPTY = empty();

function balance(c, l, v, r) {

  if (c === RED && 
      l !== null && l.color === RED && 
      l.left !== null && l.left.color === RED) {
    return new RBNode(RED,
      new RBNode(BLACK, l.left, l.value, l.right),
      l.value,
      new RBNode(BLACK, NODE_EMPTY, v, r));
     }

  if (c === RED &&
      l !== null && l.color === RED &&
      l.right !== null && l.right.color === RED) {
    const nll = new RBNode(BLACK, NODE_EMPTY, l.value, l.left);
    return new RBNode(RED,
      new RBNode(BLACK, NODE_EMPTY, l.right.value, nll),
      l.right.value,
      r);
     }

  if (c === RED &&
       r !== null && r.color === RED &&
       r.right !== null && r.right.color === RED) {
    return new RBNode(RED,
      new RBNode(BLACK, NODE_EMPTY, v, r.left),
      r.value,
      new RBNode(BLACK, r.right, r.value, NODE_EMPTY));
     }

  if (c === RED &&
       r !== null && r.color === RED &&
       r.left !== null && r.left.color === RED) {
    const nl = new RBNode(BLACK, r.left.left, r.left.value, NODE_EMPTY);
    const nr = new RBNode(BLACK, NODE_EMPTY, r.value, r.right);
    return new RBNode(RED,
      l,
      r.left.value,
      new RBNode(BLACK, nl, NODE_EMPTY, nr));
     }

  return new RBNode(c, l, v, r);
}

function insert(x, tree) {
  function insertRec(v, node) {
    if (node === null) {
      return new RBNode(RED, NODE_EMPTY, v, NODE_EMPTY);
       }

    let result;
    if (v < node.value) {
      const newLeft = insertRec(v, node.left);
      result = balance(node.color, newLeft, node.value, node.right);
        } else if (v > node.value) {
      const newRight = insertRec(v, node.right);
      result = balance(node.color, node.left, node.value, newRight);
