from __future__ import annotations

from dataclasses import dataclass
from enum import Enum


class Color(Enum):
    Red = 0
    Black = 1


@dataclass
class Node:
    color: Color
    left: "Node | None"
    value: int
    right: "Node | None"


def is_red(node: "Node | None") -> bool:
    return node is not None and node.color == Color.Red


def balance(color: Color, left: "Node | None", value: int, right: "Node | None") -> "Node | None":
    if color == Color.Black:
        return Node(Color.Black, left, value, right)

     # left-left: left red, left.left red
        # left = Node(Red, A, y, B), A = left.left = Node(Red, A1, x, A2)
        # -> Node(Red, Node(Black, A1, x, A2), y, Node(Black, B, value, right))
    if is_red(left) and is_red(left.left):
        a = left.left
        return Node(
            Color.Red,
            Node(Color.Black, a.left, a.value, a.right),
            left.value,
            Node(Color.Black, left.right, value, right),
        )

     # left-right: left red, left.right red
        # left = Node(Red, A, y, B), B = left.right = Node(Red, B1, z, B2)
        # -> Node(Red, Node(Black, A, y, B1), z, Node(Black, B2, value, right))
    if is_red(left) and is_red(left.right):
        b = left.right
        return Node(
            Color.Red,
            Node(Color.Black, left.left, left.value, b.left),
            b.value,
            Node(Color.Black, b.right, value, right),
        )

     # right-left: right red, right.left red
        # right = Node(Red, A, y, B), A = right.left = Node(Red, A1, z, A2)
        # -> Node(Red, Node(Black, left, value, A1), y, Node(Black, A2, z, B))
    if is_red(right) and is_red(right.left):
        a = right.left
        return Node(
            Color.Red,
            Node(Color.Black, left, value, a.left),
            a.value,
            Node(Color.Black, a.right, right.value, right.right),
         )

     # right-right: right red, right.right red
        # right = Node(Red, A, y, B), B = right.right = Node(Red, B1, z, B2)
        # -> Node(Red, Node(Black, left, value, A), y, Node(Black, B1, z, B2))
    if is_red(right) and is_red(right.right):
        b = right.right
        return Node(
            Color.Red,
            Node(Color.Black, left, value, right.left),
            right.value,
            Node(Color.Black, b.left, b.value, b.right),
        )

    return Node(color, left, value, right)


def insert(x: int, tree: "Node | None") -> "Node | None":
    if tree is None:
        return Node(Color.Red, None, x, None)
    if x < tree.value:
        new_left = insert(x, tree.left)
        return balance(tree.color, new_left, tree.value, tree.right)
    if x > tree.value:
        new_right = insert(x, tree.right)
        return balance(tree.color, tree.left, tree.value, new_right)
    return tree


def recolor_black(tree: "Node | None") -> "Node | None":
    if tree is None:
        return tree
    return Node(Color.Black, tree.left, tree.value, tree.right)


def insert_value(x: int, tree: "Node | None") -> "Node | None":
    return recolor_black(insert(x, tree))


def inorder(tree: "Node | None") -> list[int]:
    if tree is None:
        return []
    return inorder(tree.left) + [tree.value] + inorder(tree.right)


def main() -> None:
    tree: "Node | None" = None
    for x in [7, 3, 18, 10, 22, 8, 11, 26]:
        tree = insert_value(x, tree)
    print(inorder(tree))


if __name__ == "__main__":
    main()

