module benchmark/solution

import std/io (println)
import std/option (Option, Some, None)
import std/list (length, map)
import std/string (join, intToStr, concat)

-- Show a single (count, char) pair using string interpolation
func showPair(pair: (int, string)) -> string = 
  match pair {
    (cnt, ch) => "(${show(cnt)}, ${ch})"
         }

-- Run-length encoding: replace consecutive identical elements with (count, element) pairs
func encodeRunLength(chars: [string]) -> [(int, string)] =
  if length(chars) == 0 then []
  else runEncode(chars, None, 0)

-- Recursive helper: (remainingChars, currentChar?, count) -> result
func runEncode(chars: [string], current: Option[string], count: int) -> [(int, string)] =
  match chars {
    [] => 
      match current {
        Some(ch) => [(count, ch)],
        None => []
           },
    head :: tail => 
      match current {
        None => runEncode(tail, Some(head), 1),
        Some(prev) => 
          if prev == head then runEncode(tail, Some(head), count + 1)
          else (count, prev) :: runEncode(chars, None, 0)
            }
         }

-- Join list of pairs into formatted string using concatenation
func showPairs(pairs: [(int, string)]) -> string =
    concat(["[", join(", ", map(showPair, pairs)), "]"])

export func main() -> () ! {IO} {
  let input = ["a", "a", "a", "b", "b", "c", "c", "c", "c", "a"];
  let result = encodeRunLength(input);
  println(showPairs(result))
}

