package main

import "fmt"

type pair struct {
	count int
	char  string
}

func runLengthEncode(chars []string) []pair {
	if len(chars) == 0 {
		return []pair{}
	}

	var result []pair
	currentChar := chars[0]
	count := 1

	for i := 1; i < len(chars); i++ {
		if chars[i] == currentChar {
			count++
		} else {
			result = append(result, pair{count, currentChar})
			currentChar = chars[i]
			count = 1
		}
	}

	result = append(result, pair{count, currentChar})
	return result
}

func formatOutput(pairs []pair) string {
	var output string
	for i, p := range pairs {
		if i > 0 {
			output += ", "
		}
		output += fmt.Sprintf("(%d, %s)", p.count, p.char)
	}
	return "[" + output + "]"
}

func main() {
	chars := []string{"a", "a", "a", "b", "b", "c", "c", "c", "c", "a"}
	pairs := runLengthEncode(chars)
	fmt.Println(formatOutput(pairs))
}

