function encode(chars) {
  if (chars.length === 0) return [];

  const result = [];
  let count = 1;

  for (let i = 1; i <= chars.length; i++) {
    if (i < chars.length && chars[i] === chars[i - 1]) {
      count++;
    } else {
      result.push([count, chars[i - 1]]);
      count = 1;
    }
  }

  return result;
}

function formatOutput(encoded) {
  const pairs = encoded.map(([count, char]) => `(${count}, ${char})`);
  return `[${pairs.join(', ')}]`;
