def run_length_encode(chars: list[str]) -> list[tuple[int, str]]:
    result: list[tuple[int, str]] = []
    if not chars:
        return result
    count = 1
    current = chars[0]
    for ch in chars[1:]:
        if ch == current:
            count += 1
        else:
            result.append((count, current))
            current = ch
            count = 1
    result.append((count, current))
    return result


