-- Transition function: exhaustive pattern matching
func transition(s: State, e: Event) -> State {
  match (s, e) {
    -- Idle + Call
    (Idle(floor), Call(target)) => 
      if target == floor then DoorOpen(floor, 3) else Moving(floor, target),

