func (Call) isEvent() {}

type Tick struct{}

func (Tick) isEvent() {}

type Arrive struct{}

func (Arrive) isEvent() {}

func transition(state State, event Event) State {
	switch s := state.(type) {
	case Idle:
		switch event.(type) {
		case Call:
			ev := event.(Call)
			if ev.floor == s.floor {
				return DoorOpen{floor: s.floor, timer: 3}
				} else {
				return Moving{current: s.floor, target: ev.floor}
				}
		default:
			return state
			}
	case Moving:
		switch event.(type) {
