module benchmark/solution

import std/io (println)
import std/string (intToStr)
import std/result (Result, Ok, Err)

-- State types
type State = Idle | HasCredit(int) | Dispensing(int)

-- Event types
type Event = Insert(int) | Select(int) | DispenseDone

-- Print state helper
func printOk(state: State) -> () ! {IO} {
  match state {
    Idle => println("ok: IDLE"),
    HasCredit(c) => println("ok: CREDIT(${show(c)})"),
    Dispensing(ch) => println("ok: DISPENSING(${show(ch)})")
  }
}

-- Print error helper
func printErr(reason: string) -> () ! {IO} {
  println("err: ${reason}")
}

-- Get price for item code
pure func getPrice(code: int) -> int {
  match code {
    1 => 125,
    2 => 75,
    3 => 100,
    _ => 0
  }
}

-- Step function with exhaustive pattern matching on (state, event)
pure func step(state: State, event: Event) -> Result[State, string] ! {} {
  match (state, event) {
    -- Idle state transitions
    (Idle, Insert(n)) => Ok(HasCredit(n)),
    (Idle, Select(_)) => Err("no_credit"),
    (Idle, DispenseDone) => Err("not_dispensing"),

    -- HasCredit state transitions
    (HasCredit(c), Insert(n)) => Ok(HasCredit(c + n)),
    (HasCredit(c), Select(code)) => {
      let price = getPrice(code);
      if code < 1 || code > 3 then Err("unknown_item")
      else if c < price then Err("insufficient_funds")
      else Ok(Dispensing(c - price))
    },
    (HasCredit(_), DispenseDone) => Err("not_dispensing"),

    -- Dispensing state transitions
    (Dispensing(_), Insert(_)) => Err("busy"),
    (Dispensing(_), Select(_)) => Err("busy"),
    (Dispensing(ch), DispenseDone) => Ok(Idle)
  }
}

-- Simulation runner for a sequence of events and initial state
pure func runSimulation(init: State, events: [Event]) -> () ! {IO} {
  letrec loop = \state xs. match xs {
     [] => (),
    head :: rest => {
      match step(state, head) {
        Ok(newState) => {
          printOk(newState);
          loop(newState, rest)
          },
        Err(reason) => {
          printErr(reason);
          loop(state, rest)
          }
         }
       }
     };
  loop(init, events);
   ()
}

export func main() -> () ! {IO} {
  let events = [
    Insert(50),
    Select(1),
    Insert(100),
    Select(1),
    Insert(50),
    DispenseDone,
    Select(2),
    Insert(100),
    Select(2),
    DispenseDone
  ];
  runSimulation(Idle, events)
}

