// Event types
type Event interface {
	event()
}

type InsertEvent struct {
	cents int
}

func (InsertEvent) event() {}

type SelectEvent struct {
	code int
}

func (SelectEvent) event() {}

type DispenseDoneEvent struct{}

func (DispenseDoneEvent) event() {}

// Result type
type Result struct {
	ok   bool
	state State
	err   string
}

func Ok(s State) Result {
	return Result{ok: true, state: s}
}

func Err(e string) Result {
	return Result{ok: false, err: e}
}

// Helper functions to create events
func Insert(cents int) Event {
	return InsertEvent{cents: cents}
}

func Select(code int) Event {
	return SelectEvent{code: code}
}

func DispenseDone() Event {
	return DispenseDoneEvent{}
}

// Price lookup by code
func price(code int) int {
	switch code {
	case 1:
		return 125
	case 2:
		return 75
	case 3:
		return 100
	default:
		return 0
	}
}

// State printer
func printState(s State) string {
	switch v := s.(type) {
	case IdleState:
		return "IDLE"
	case HasCreditState:
		return fmt.Sprintf("CREDIT(%d)", v.cents)
	case DispensingState:
		return fmt.Sprintf("DISPENSING(%d)", v.change)
	default:
		return "UNKNOWN"
	}
}

// Step function implementing the state machine transitions
func step(state State, event Event) Result {
	switch e := event.(type) {
	case InsertEvent:
		switch state.(type) {
		case IdleState:
			return Ok(HasCreditState{cents: e.cents})
		case HasCreditState:
			hcs := state.(HasCreditState)
			return Ok(HasCreditState{cents: hcs.cents + e.cents})
		case DispensingState:
			return Err("busy")
		default:
			return Err("unknown state")
		}

	case SelectEvent:
		switch state.(type) {
		case IdleState:
			return Err("no_credit")
		case HasCreditState:
			hcs := state.(HasCreditState)
			itemPrice := price(e.code)

			if e.code != 1 && e.code != 2 && e.code != 3 {
				return Err("unknown_item")
			} else if hcs.cents < itemPrice {
				return Err("insufficient_funds")
			} else {
				change := hcs.cents - itemPrice
				return Ok(DispensingState{change: change})
			}
		case DispensingState:
			return Err("busy")
		default:
			return Err("unknown state")
		}

	case DispenseDoneEvent:
		switch state.(type) {
		case IdleState:
			return Err("not_dispensing")
		case HasCreditState:
			return Err("not_dispensing")
		case DispensingState:
			return Ok(IdleState{})
		default:
			return Err("unknown state")
		}

	default:
		return Err("unknown event")
	}
