    else if (s.tag === 'HasCredit') console.log(`ok: CREDIT(${s.value})`);
    else if (s.tag === 'Dispensing') console.log(`ok: DISPENSING(${s.value})`);
  } else {
    console.log(`err: ${result.error}`);
  }
}

function step(state, event) {
  switch (state.tag) {
    case 'Idle': {
      if (event.tag === 'Insert') {
        return { ok: true, state: { tag: 'HasCredit', value: event.value } };
      } else if (event.tag === 'Select') {
        return { ok: false, error: 'no_credit' };
      } else if (event.tag === 'DispenseDone') {
        return { ok: false, error: 'not_dispensing' };
      }
      break;
    }
    case 'HasCredit': {
      if (event.tag === 'Insert') {
        return { ok: true, state: { tag: 'HasCredit', value: state.value + event.value } };
      } else if (event.tag === 'Select') {
        const code = event.value;
        if (!validCodes.has(code)) {
          return { ok: false, error: 'unknown_item' };
        }
        const itemPrice = price(code);
        if (state.value < itemPrice) {
          return { ok: false, error: 'insufficient_funds' };
        }
        return {
          ok: true,
          state: { tag: 'Dispensing', value: state.value - itemPrice },
        };
      } else if (event.tag === 'DispenseDone') {
        return { ok: false, error: 'not_dispensing' };
      }
      break;
    }
    case 'Dispensing': {
      if (event.tag === 'Insert' || event.tag === 'Select') {
        return { ok: false, error: 'busy' };
      } else if (event.tag === 'DispenseDone') {
        return { ok: true, state: { tag: 'Idle', value: 0 } };
      }
