import std/string (concat)

type Expr = Const(int) | Var(string) | Add(Expr, Expr) | Mul(Expr, Expr)

pure func exprEq(a: Expr, b: Expr) -> bool ! {} {
  match (a, b) {
    (Const(n1), Const(n2)) => n1 == n2,
    (Var(name1), Var(name2)) => name1 == name2,
    (Add(l1, r1), Add(l2, r2)) => exprEq(l1, l2) && exprEq(r1, r2),
    (Mul(l1, r1), Mul(l2, r2)) => exprEq(l1, l2) && exprEq(r1, r2),
    (_, _) => false
  }
}

pure func diff(expr: Expr, var: string) -> Expr ! {} {
  match expr {
    Const(_) => Const(0),
    Var(name) => if name == var then Const(1) else Const(0),
    Add(a, b) => Add(diff(a, var), diff(b, var)),
    Mul(a, b) => Add(Mul(a, diff(b, var)), Mul(b, diff(a, var)))
  }
}

pure func simplify(expr: Expr) -> Expr ! {} {
  match expr {
    Const(_) => expr,
    Var(_) => expr,
    Add(a, b) => simplifyAdd(simplify(a), simplify(b)),
    Mul(a, b) => simplifyMul(simplify(a), simplify(b))
   }
}

pure func simplifyAdd(a: Expr, b: Expr) -> Expr ! {} {
  if exprEq(a, Const(0)) then b else if exprEq(b, Const(0)) then a else Add(a, b)
}

pure func simplifyMul(a: Expr, b: Expr) -> Expr ! {} {
  if exprEq(a, Const(0)) || exprEq(b, Const(0)) then Const(0) else
    if exprEq(a, Const(1)) then b else if exprEq(b, Const(1)) then a else Mul(a, b)
}

pure func showExpr(expr: Expr) -> string ! {} {
  match expr {
    Const(n) => show(n),
    Var(name) => name,
    Add(a, b) => concat(["(", showExpr(a), " + ", showExpr(b), ")"]),
    Mul(a, b) => concat(["(", showExpr(a), " * ", showExpr(b), ")"])
    }
}

