func (Const) isExpr() {}

type Var struct {
	name string
}

func (Var) isExpr() {}

type Add struct {
	left, right Expr
}

func (Add) isExpr() {}

type Mul struct {
	left, right Expr
}

func (Mul) isExpr() {}

func makeAdd(left, right Expr) Expr {
	sLeft := simplify(left)
	sRight := simplify(right)
	if c, ok := sLeft.(Const); ok && c.val == 0 {
		return sRight
	}
	if c, ok := sRight.(Const); ok && c.val == 0 {
		return sLeft
	}
	return Add{left: sLeft, right: sRight}
}

func makeMul(left, right Expr) Expr {
	sLeft := simplify(left)
	sRight := simplify(right)
	if c, ok := sLeft.(Const); ok && c.val == 0 {
		return Const{0}
	}
	if c, ok := sRight.(Const); ok && c.val == 0 {
		return Const{0}
	}
	if c, ok := sLeft.(Const); ok && c.val == 1 {
		return sRight
	}
	if c, ok := sRight.(Const); ok && c.val == 1 {
		return sLeft
	}
	return Mul{left: sLeft, right: sRight}
}

func diff(e Expr, v string) Expr {
	switch expr := e.(type) {
	case Const:
		return Const{0}
	case Var:
		if expr.name == v {
			return Const{1}
		}
		return Const{0}
	case Add:
		return makeAdd(diff(expr.left, v), diff(expr.right, v))
	case Mul:
		return makeAdd(
			makeMul(expr.left, diff(expr.right, v)),
			makeMul(expr.right, diff(expr.left, v)),
		)
	}
	return Const{0}
}

func simplify(e Expr) Expr {
	switch expr := e.(type) {
	case Const:
		return e
	case Var:
		return e
	case Add:
		return makeAdd(expr.left, expr.right)
	case Mul:
		return makeMul(expr.left, expr.right)
	}
	return e
}

