// Expression AST constructors
function Const(n) {
    return { type: 'Const', value: n };
}

function Var(name) {
    return { type: 'Var', name: name };
}

function Add(left, right) {
    return { type: 'Add', left, right };
}

function Mul(left, right) {
    return { type: 'Mul', left, right };
}

// Symbolic differentiation
function diff(expr, varName) {
    switch (expr.type) {
        case 'Const':
            return Const(0);
        case 'Var':
            if (expr.name === varName) {
                return Const(1);
            } else {
                return Const(0);
            }
        case 'Add':
            return Add(diff(expr.left, varName), diff(expr.right, varName));
        case 'Mul':
            // Product rule: d/dx(f * g) = f * d/dx(g) + g * d/dx(f)
            return Add(
                Mul(expr.left, diff(expr.right, varName)),
                Mul(expr.right, diff(expr.left, varName))
            );
        default:
            throw new Error(`Unknown expression type: ${expr.type}`);
    }
}

// Simplification rules
function simplify(expr) {
    switch (expr.type) {
        case 'Const':
        case 'Var':
            return expr;
        case 'Add':
            const left = simplify(expr.left);
            const right = simplify(expr.right);
            if (left.type === 'Const' && left.value === 0) return right;
            if (right.type === 'Const' && right.value === 0) return left;
            return Add(left, right);
        case 'Mul':
            const l = simplify(expr.left);
            const r = simplify(expr.right);
            if (l.type === 'Const' && l.value === 0) return Const(0);
            if (r.type === 'Const' && r.value === 0) return Const(0);
            if (l.type === 'Const' && l.value === 1) return r;
            if (r.type === 'Const' && r.value === 1) return l;
            return Mul(l, r);
        default:
            throw new Error(`Unknown expression type: ${expr.type}`);
    }
}

// Convert AST to readable string
function showExpr(expr) {
    switch (expr.type) {
        case 'Const':
            return String(expr.value);
        case 'Var':
            return expr.name;
        case 'Add':
            return `(${showExpr(expr.left)} + ${showExpr(expr.right)})`;
        case 'Mul':
            return `(${showExpr(expr.left)} * ${showExpr(expr.right)})`;
        default:
            throw new Error(`Unknown expression type: ${expr.type}`);
    }
}

// Main function
function main() {
    // Create expression: x^2 + 3x + 5 = Add(Add(Mul(x, x), Mul(Const(3), x)), Const(5))
    const expr = Add(
        Add(Mul(Var('x'), Var('x')), Mul(Const(3), Var('x'))),
        Const(5)
    );

    // Differentiate with respect to 'x'
    const derivative = diff(expr, 'x');

    // Simplify the result
    const simplified = simplify(derivative);

    // Print the result
    console.log(showExpr(simplified));
}

main();

