from dataclasses import dataclass
from typing import Union


@dataclass
class Const:
    val: int


@dataclass
class Var:
    name: str


@dataclass
class Add:
    left: "Expr"
    right: "Expr"


@dataclass
class Mul:
    left: "Expr"
    right: "Expr"


Expr = Union[Const, Var, Add, Mul]


def diff(expr: Expr, var: str) -> Expr:
    match expr:
        case Const(_):
            return Const(0)
        case Var(name):
            return Const(1) if name == var else Const(0)
        case Add(f, g):
            return Add(diff(f, var), diff(g, var))
        case Mul(f, g):
            return Add(
                Mul(f, diff(g, var)),
                Mul(g, diff(f, var)),
            )


def simplify(expr: Expr) -> Expr:
    match expr:
        case Const(_) | Var(_):
            return expr
        case Add(f, g):
            f = simplify(f)
            g = simplify(g)
            if isinstance(f, Const) and f.val == 0:
                return g
            if isinstance(g, Const) and g.val == 0:
                return f
            return Add(f, g)
        case Mul(f, g):
            f = simplify(f)
            g = simplify(g)
            if isinstance(f, Const) and f.val == 0 or isinstance(g, Const) and g.val == 0:
                return Const(0)
            if isinstance(f, Const) and f.val == 1:
                return g
            if isinstance(g, Const) and g.val == 1:
                return f
            return Mul(f, g)


def showExpr(expr: Expr) -> str:
    match expr:
        case Const(v):
            return str(v)
        case Var(name):
            return name
        case Add(a, b):
            return f"({showExpr(a)} + {showExpr(b)})"
        case Mul(a, b):
            return f"({showExpr(a)} * {showExpr(b)})"


