pure func mapTree(fn: int -> int, tree: Tree) -> Tree =
  match tree {
    Leaf(val) => Leaf(fn(val)),
    Node(left, val, right) => Node(mapTree(fn, left), fn(val), mapTree(fn, right))
  }

// foldTree: in-order fold over tree values
pure func foldTree(fn: (int, int) -> int, acc: int, tree: Tree) -> int =
  match tree {
    Leaf(val) => fn(acc, val),
    Node(left, val, right) => {
      let afterLeft = foldTree(fn, acc, left);
      let afterVal = fn(afterLeft, val);
      foldTree(fn, afterVal, right)
     }
  }

// treeToList: in-order traversal returning list of integers
pure func treeToList(tree: Tree) -> [int] =
  match tree {
    Leaf(val) => [val],
    Node(left, val, right) => treeToList(left) ++ [val] ++ treeToList(right)
  }

// treeDepth: return maximum depth of tree (Leaf has depth 1)
pure func treeDepth(tree: Tree) -> int =
  match tree {
    Leaf(_) => 1,
    Node(left, _, right) => {
      let leftDepth = treeDepth(left);
      let rightDepth = treeDepth(right);
      if leftDepth > rightDepth then leftDepth + 1 else rightDepth + 1
