package main

import "fmt"

type Tree struct {
	isLeaf bool
	left   *Tree
	val    int
	right  *Tree
}

func leaf(v int) *Tree {
	return &Tree{isLeaf: true, val: v}
}

func node(l *Tree, v int, r *Tree) *Tree {
	return &Tree{isLeaf: false, left: l, val: v, right: r}
}

func mapTree(fn func(int) int, t *Tree) *Tree {
	if t.isLeaf {
		return leaf(fn(t.val))
	}
	return node(mapTree(fn, t.left), fn(t.val), mapTree(fn, t.right))
}

func foldTree(fn func(int, int) int, acc int, t *Tree) int {
	if t.isLeaf {
		return fn(acc, t.val)
	}
	acc = foldTree(fn, acc, t.left)
	acc = fn(acc, t.val)
	acc = foldTree(fn, acc, t.right)
	return acc
}

func treeToList(t *Tree) []int {
	if t.isLeaf {
		return []int{t.val}
	}
	result := treeToList(t.left)
	result = append(result, t.val)
	result = append(result, treeToList(t.right)...)
	return result
}

func treeDepth(t *Tree) int {
	if t.isLeaf {
		return 1
	}
	leftD := treeDepth(t.left)
	rightD := treeDepth(t.right)
	if leftD > rightD {
		return leftD + 1
	}
	return rightD + 1
}

func formatList(lst []int) string {
	result := "["
	for i, v := range lst {
		if i > 0 {
			result += ", "
		}
		result += fmt.Sprintf("%d", v)
	}
	result += "]"
	return result
}

