module benchmark/solution
import std/option (Option, Some, None)

-- Type ADT for unification
type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)

-- Substitution is a list of (varName, Type) pairs
type Subst = [(string, Type)]

-- Helper: find a variable in a substitution
func lookup(name: string, subst: Subst) -> Option[Type] {
  match subst {
    [] => None,
    (kv, v) :: rest => if kv == name then Some(v) else lookup(name, rest)
   }
}

-- Apply substitution to a type
func apply(subst: Subst, t: Type) -> Type {
  match t {
    TVar(name) => match lookup(name, subst) {
      Some(t2) => apply(subst, t2),
      None => t
     },
    TInt => TInt,
    TBool => TBool,
    TFunc(arg, ret) => TFunc(apply(subst, arg), apply(subst, ret))
   }
}

-- Concatenate two substitutions (applying s1 then s2)
func compose(s1: Subst, s2: Subst) -> Subst {
  match s1 {
    [] => s2,
    (kv, t) :: rest => (kv, apply(s2, t)) :: compose(rest, s2)
   }
}

-- Unify two types, returns Option[Subst] (None = fail)
func unify(t1: Type, t2: Type) -> Option[Subst] {
  match (t1, t2) {
    (TInt, TInt) => Some([]),
    (TBool, TBool) => Some([]),
    (TVar(a), t) => Some([(a, t)]),
    (t, TVar(a)) => Some([(a, t)]),
    (TFunc(a1, r1), TFunc(a2, r2)) => match unify(a1, a2) {
      None => None,
      Some(s1) => match unify(apply(s1, r1), apply(s1, r2)) {
        Some(s2) => Some(compose(s2, s1)),
        None => None
       }
     },
    _ => None
   }
}

export func main() -> () ! {IO} {
  -- TFunc(TVar("a"), TInt) vs TFunc(TBool, TVar("b"))
  let t1 = TFunc(TVar("a"), TInt);
  let t2 = TFunc(TBool, TVar("b"));

  match unify(t1, t2) {
    Some(subst) => {
      let aVal = lookup("a", subst);
      let bVal = lookup("b", subst);

      match (aVal, bVal) {
        (Some(TBool), Some(TInt)) => {
          println("a = TBool");
          println("b = TInt")
        },
        _ => println("Unification failed unexpectedly")
       }
     },
    None => println("Unification failed")
   }
}

