package main

import "fmt"

// Type represents a type in the type system
type Type interface {
	isType()
}

// TVar is a type variable (e.g., "a", "b")
type TVar struct {
	Name string
}

func (TVar) isType() {}

// TInt is the integer type
type TInt struct{}

func (TInt) isType() {}

// TBool is the boolean type
type TBool struct{}

func (TBool) isType() {}

// TFunc is a function type: arg -> result
type TFunc struct {
	Arg  Type
	Ret  Type
}

func (TFunc) isType() {}

// Substitution is a list of (varName, Type) pairs
type Substitution []struct {
	Var string
	Typ Type
}

func makeSubst(pair ...struct{ Var string; Typ Type }) Substitution {
	return pair
}

// apply applies the substitution to a type
func apply(subst Substitution, t Type) Type {
	switch typ := t.(type) {
	case TVar:
		for _, s := range subst {
			if s.Var == typ.Name {
				return apply(subst, s.Typ)
				}
			}
		return typ
	case TInt:
		return typ
	case TBool:
		return typ
	case TFunc:
		return TFunc{
			Arg: apply(subst, typ.Arg),
			Ret: apply(subst, typ.Ret),
			}
	default:
		return t
	}
}

// unify unifies two types and returns a substitution (or nil if they don't unify)
func unify(t1, t2 Type) (Substitution, error) {
	switch v1 := t1.(type) {
	case TVar:
		if v2, ok := t2.(TVar); ok {
			fmt.Printf("unify(TVar(%s), TVar(%s))\n", v1.Name, v2.Name)
			if v1.Name == v2.Name {
				return Substitution{}, nil
				}
			fmt.Printf("  -> [(%s, TVar)]\n", v1.Name)
			return makeSubst(struct{ Var string; Typ Type }{v1.Name, t2}), nil
			}
		switch v2 := t2.(type) {
		case TBool:
			fmt.Printf("unify(TVar(%s), TBool)\n", v1.Name)
			return makeSubst(struct{ Var string; Typ Type }{v1.Name, v2}), nil
		case TInt:
			fmt.Printf("unify(TVar(%s), TInt)\n", v1.Name)
			return makeSubst(struct{ Var string; Typ Type }{v1.Name, v2}), nil
		case TFunc:
			fmt.Printf("unify(TVar(%s), TFunc)\n", v1.Name)
			return makeSubst(struct{ Var string; Typ Type }{v1.Name, v2}), nil
		default:
			return nil, fmt.Errorf("cannot unify")
			}
	case TInt:
		if _, ok := t2.(TInt); ok {
			fmt.Printf("unify(TInt, TInt) -> []\n")
			return Substitution{}, nil
			}
		return nil, fmt.Errorf("cannot unify")
	case TBool:
		if _, ok := t2.(TBool); ok {
			fmt.Printf("unify(TBool, TBool) -> []\n")
			return Substitution{}, nil
			}
		return nil, fmt.Errorf("cannot unify")
	case TFunc:
		switch v2 := t2.(type) {
		default:
			return nil, fmt.Errorf("cannot unify")
		case TVar:
			fmt.Printf("unify(TFunc, TVar(%s))\n", v2.Name)
			return makeSubst(struct{ Var string; Typ Type }{v2.Name, t1}), nil
		case TFunc:
			fmt.Printf("unify(TFunc, TFunc)\n")
			subst1, err := unify(v1.Arg, v2.Arg)
			if err != nil {
				return nil, err
				}
			fmt.Printf("  subst1 = %v\n", subst1)
			appliedV1Ret := apply(subst1, v1.Ret)
			appliedV2Ret := apply(subst1, v2.Ret)
			fmt.Printf("  appliedV1Ret = %T, appliedV2Ret = %T\n", appliedV1Ret, appliedV2Ret)
			subst2, err := unify(appliedV1Ret, appliedV2Ret)
			if err != nil {
				return nil, err
				}
			fmt.Printf("  subst2 = %v\n", subst2)
			result := make(Substitution, len(subst1)+len(subst2))
			copy(result, subst1)
			for i, s := range subst2 {
				result[len(subst1)+i] = struct{ Var string; Typ Type }{s.Var, apply(subst1, s.Typ)}
				}
			fmt.Printf("  final result = %v\n", result)
			return result, nil
			}
	default:
		return nil, fmt.Errorf("cannot unify")
	}
}

func main() {
	t1 := TFunc{Arg: TVar{"a"}, Ret: TInt{}}
	t2 := TFunc{Arg: TBool{}, Ret: TVar{"b"}}

	subst, err := unify(t1, t2)
	if err != nil {
		fmt.Println("Failed to unify")
		return
	}

	for _, s := range subst {
		var typeStr string
		switch s.Typ.(type) {
		case TBool:
			typeStr = "TBool"
		case TInt:
			typeStr = "TInt"
		case TVar:
			typeStr = "TVar(" + s.Typ.(TVar).Name + ")"
		default:
			typeStr = "unknown"
			}
		fmt.Printf("%s = %s\n", s.Var, typeStr)
	}
}

