class Type {
  constructor(tag, left = null, right = null) {
    this.tag = tag;
    this.left = left;
    this.right = right;
  }

  static TVar(name) { return new Type('TVar', name); }
  static TInt() { return new Type('TInt'); }
  static TBool() { return new Type('TBool'); }
  static TFunc(arg, result) { return new Type('TFunc', arg, result); }
}

class Substitution {
  constructor(pairs = []) {
    this.pairs = pairs; // Array of [varName, Type]
  }

  isEmpty() {
    return this.pairs.length === 0;
  }
}

function cloneType(type) {
  if (type.tag === 'TVar') {
    return Type.TVar(type.left);
  } else if (type.tag === 'TFunc') {
    return Type.TFunc(cloneType(type.left), cloneType(type.right));
  }
  return new Type(type.tag);
}

function getTypeLabel(type) {
  if (type.tag === 'TVar') return `TVar("${type.left}")`;
  if (type.tag === 'TInt') return 'TInt';
  if (type.tag === 'TBool') return 'TBool';
  if (type.tag === 'TFunc') return `${getTypeLabel(type.left)} -> ${getTypeLabel(type.right)}`;
  return type.tag;
}

function unify(t1, t2, subst = new Substitution()) {
  const substT1 = applySubst(subst, t1);
  const substT2 = applySubst(subst, t2);

  if (substT1.tag === 'TVar' && substT2.tag === 'TVar') {
    if (substT1.left === substT2.left) return subst;
    return new Substitution([...subst.pairs, [substT1.left, cloneType(substT2)]]);
  }

  if (substT1.tag === 'TVar') {
    if (!isFreeIn(substT1.left, substT2)) {
      return new Substitution([...subst.pairs, [substT1.left, cloneType(substT2)]]);
    }
    return null;
  }

  if (substT2.tag === 'TVar') {
    if (!isFreeIn(substT2.left, substT1)) {
      return new Substitution([...subst.pairs, [substT2.left, cloneType(substT1)]]);
    }
    return null;
  }

  if (substT1.tag === 'TInt' && substT2.tag === 'TInt') return subst;
  if (substT1.tag === 'TBool' && substT2.tag === 'TBool') return subst;

  if (substT1.tag === 'TFunc' && substT2.tag === 'TFunc') {
    const subst1 = unify(substT1.left, substT2.left, subst);
    if (!subst1) return null;
    return unify(substT1.right, substT2.right, subst1);
  }

  return null;
}

function applySubst(subst, type) {
  if (subst.isEmpty()) return cloneType(type);

  for (const [varName, t] of subst.pairs) {
    if (type.tag === 'TVar') {
      if (type.left === varName) {
        return cloneType(t);
      }
    } else if (type.tag === 'TFunc') {
      type.left = applySubst(subst, type.left);
      type.right = applySubst(subst, type.right);
    }
  }
  return cloneType(type);
}

function isFreeIn(varName, type) {
  if (type.tag === 'TVar') return type.left === varName;
  if (type.tag === 'TFunc') {
    return isFreeIn(varName, type.left) || isFreeIn(varName, type.right);
  }
  return false;
}

function main() {
  const t1 = Type.TFunc(Type.TVar('a'), Type.TInt());
  const t2 = Type.TFunc(Type.TBool(), Type.TVar('b'));

  const result = unify(t1, t2);

  for (const [varName, type] of result.pairs) {
    console.log(`${varName} = ${getTypeLabel(type)}`);
  }
}

main();

