from __future__ import annotations
from dataclasses import dataclass
from typing import List, Optional


class Type:
    pass


@dataclass
class TVar(Type):
    name: str


@dataclass
class TInt(Type):
    pass


@dataclass
class TBool(Type):
    pass


@dataclass
class TFunc(Type):
    arg: Type
    res: Type


Subst = List


def apply(subst, t) -> Optional[Type]:
    if isinstance(t, TVar):
        for var, value in subst:
            if var == t.name:
                return apply(subst, value)
        return t
    elif isinstance(t, TFunc):
        a = apply(subst, t.arg)
        r = apply(subst, t.res)
        if a is None or r is None:
            return None
        return TFunc(a, r)
    else:
        return t


def unify(t1, t2) -> Optional[Subst]:
    if isinstance(t1, TInt) and isinstance(t2, TInt):
        return []
    if isinstance(t1, TBool) and isinstance(t2, TBool):
        return []
    if isinstance(t1, TVar):
        return [(t1.name, t2)]
    if isinstance(t2, TVar):
        return [(t2.name, t1)]
    if isinstance(t1, TFunc) and isinstance(t2, TFunc):
        s1 = unify(t1.arg, t2.arg)
        if s1 is None:
            return None
        s2 = unify(t1.res, t2.res)
        if s2 is None:
            return None
        return s1 + s2
    return None


def main() -> None:
    t1 = TFunc(TVar("a"), TInt())
    t2 = TFunc(TBool(), TVar("b"))
    s = unify(t1, t2)
    if s is None:
        print("No unification")
        return
    for var, typ in s:
        if isinstance(typ, TBool):
            print(f"{var} = TBool")
        elif isinstance(typ, TInt):
            print(f"{var} = TInt")
        elif isinstance(typ, TVar):
            print(f"{var} = {typ.name}")
        elif isinstance(typ, TFunc):
            print(f"{var} = TFunc")


if __name__ == "__main__":
    main()

