module benchmark/solution

import std/option (Option, Some, None, map, flatMap)
import std/math (sqrt, intToFloat, floatToInt, round)

pure func safeDiv(a: int, b: int) -> Option[int] =
  if b == 0 then None else Some(a / b)

pure func safeSqrt(x: int) -> Option[int] =
  if x >= 0 then Some(floatToInt(round(sqrt(intToFloat(x))))) else None

pure func chain(a: int, b: int, c: int) -> Option[int] {
  let divRes = safeDiv(a, b);
  let sqrtRes = flatMap(\x. safeSqrt(x), divRes);
  map(\x. x + c, sqrtRes)
}

export func main() -> () ! {IO} {
  println(show(chain(100, 4, 1)));
  println(show(chain(100, 0, 1)));
  println(show(chain(-4, 1, 10)));
  println(show(chain(16, 4, -3)))
}
